/* B-30 (rider R-F9-5) — reSpec/overlay pack load-failure is now HONEST, never silent. When a
   GAME-VARIANTS pack fails to fetch (flaky mobile network), mods.js records it + fires
   'swrpg-mods-loaderror'; useModsLoadError() surfaces the failed stamps so the creator + the stamped
   sheet render a notice instead of silently falling back to base trees with the toggle still on. */
function useModsLoadError() {
  var _u = React.useState(function () { return (window.SWRPGMods && window.SWRPGMods.failed) ? window.SWRPGMods.failed() : []; });
  var failed = _u[0], setFailed = _u[1];
  React.useEffect(function () {
    if (!window.SWRPGMods || !window.SWRPGMods.failed) return;
    var on = function () { setFailed(window.SWRPGMods.failed()); };
    window.addEventListener('swrpg-mods-loaderror', on);
    window.addEventListener('swrpg-mods-changed', on);
    return function () { window.removeEventListener('swrpg-mods-loaderror', on); window.removeEventListener('swrpg-mods-changed', on); };
  }, []);
  return failed;  // array of stamps whose last fetch failed
}
// THE inline notice — B-27 amber pattern. role=status for SR. Extracted from ModsLoadNotice when
// B-250 needed a second one (R-B250-2 requires an EXISTING shape; inventing chrome would be a new
// surface and R-MU1's mockup lane). One shape, two messages — not a second implementation of the
// same job. `testid` lets a smoke name the specific notice rather than "some amber box".
// B-1022 (D-400, ADDENDUM 36): the COLOURS live in CSS by ground (decisions/0049), never inline — the dark-chrome
// default in lib/shared/tokens.css (`.sheet-notice*`, today's values), the paper skin in lib/shared/paper.css
// under [data-doc-ground="creator"] (frame B's tokens). Layout stays inline: it is the same on every ground.
// B-1257 (D-411 items 13–14, ADDENDUM 295 Q1 → A): `paper` opts a notice on another creator ground into the same paper
// skin (`.sheet-notice-paper`); `standalone` is a notice that IS the screen's content (a failed download) — no bottom
// margin, its measure 520px, left-aligned, as the 247 page drew both.
function SheetNotice({ children, actionLabel, onAction, testid, paper, standalone, actTestid }) {
  return (
    <div role="status" aria-live="polite" data-testid={testid} className={paper ? 'sheet-notice sheet-notice-paper' : 'sheet-notice'} style={Object.assign({
      display: 'flex', alignItems: 'center', gap: '10px', flexWrap: 'wrap',
      margin: '0 0 12px', padding: '10px 12px', borderRadius: '6px',
    }, standalone ? { margin: 0, maxWidth: '520px', width: '100%', boxSizing: 'border-box', textAlign: 'left', border: '1px solid' } : null)}>
      <span className="sheet-notice-text" style={{ flex: 1, minWidth: '180px', fontFamily: 'var(--font-body)', fontSize: 'var(--fs-sm)', lineHeight: 1.45 }}>
        {children}
      </span>
      {onAction ? (
        <button type="button" className="sheet-notice-act" data-testid={actTestid} onClick={onAction} style={{
          flexShrink: 0, minHeight: '44px', padding: '7px 16px', cursor: 'pointer',
          borderRadius: '5px',
          fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-xs)', letterSpacing: '0.14em', fontWeight: 700,
        }}>{actionLabel}</button>
      ) : null}
    </div>
  );
}

function ModsLoadNotice({ onRetry }) {
  return (
    <SheetNotice actionLabel="RETRY" onAction={onRetry} testid="notice-mods-load">
      reSpecialized data didn&rsquo;t load — showing the standard talent trees.
    </SheetNotice>
  );
}

// B-250 (R-B250-2). MECHANICS VOICE — says what happened, what is safe, and what to do, with no
// metaphor and no apology. The three facts are the ruling's; the wording is mine within them.
// DISMISS deletes the marker field, so a player who has read it never sees it again — the notice
// cannot become furniture on a character whose owner already acted on it.
function XpRepairedNotice({ onDismiss }) {
  return (
    <SheetNotice actionLabel="DISMISS" onAction={onDismiss} testid="notice-xp-repaired">
      This character&rsquo;s XP record was damaged by an old bug and has been reset to 0.
      Everything you bought is still here — only the XP totals were cleared.
      Ask your GM to re-grant your XP.
    </SheetNotice>
  );
}

