// useSwipeBack + SWIPE_BACK_EDGE_PX → window.SWRPGUI (lib/shared/ui.jsx), destructured at top. [Phase 1b]

// B-1729 (release-r7-bug-burndown ADDENDUM 548 A, 553): no browser reports a file gone silent, and a silent tag blocks the tags queued behind it. So a late file is fetched and its stream watched:
// silence past the limit aborts it and rejects (never a limit on the whole file, so a slow success can't fail). Pages answers a missing file with the shell at 200, so the type is checked. No re-ask on a timer (519).
var PLAYER_FILE_SILENCE_MS = 30000;   // moved from 20 s: Slow 3G's longest silence is about 24 s on h1, its six sockets queued behind the registries, under 4 s on h2 (gate post1-cold-mount-build)
function fetchAndRunFile(src, url) {
  var ctl = new AbortController(), timer = null;
  var watch = function() { clearTimeout(timer); timer = setTimeout(function() { ctl.abort(); }, PLAYER_FILE_SILENCE_MS); };
  watch();
  return fetch(url || src, { signal: ctl.signal }).then(function(res) {
    if (!res.ok || !/javascript/i.test(res.headers.get('content-type') || '')) throw new Error('not a script');
    watch();
    var reader = res.body.getReader(), chunks = [];
    var pump = function() { return reader.read().then(function(r) { if (r.done) return chunks; chunks.push(r.value); watch(); return pump(); }); };
    return pump();
  }).then(function(chunks) {
    clearTimeout(timer);
    return new Promise(function(resolve, reject) {
      var s = document.createElement('script');
      s.src = URL.createObjectURL(new Blob(chunks.concat('\n//# sourceURL=' + location.origin + src), { type: 'text/javascript;charset=utf-8' }));   // sourceURL: stacks and the map read the file, not blob:
      s.onload = function() { URL.revokeObjectURL(s.src); s.remove(); resolve(); };
      s.onerror = function() { URL.revokeObjectURL(s.src); s.remove(); reject(new Error('did not run')); };
      document.head.appendChild(s);
    });
  }).catch(function() { var silent = ctl.signal.aborted, e = new Error('Failed to load ' + src); clearTimeout(timer); ctl.abort(); e.silent = silent; throw e; });
}

// NPC library view loaded on demand at first use, not at boot.
var _npcLibPromise = null;
function ensureNpcLibrary() {
  if (window.SWRPGLibrary) return Promise.resolve(window.SWRPGLibrary);
  if (_npcLibPromise) return _npcLibPromise;
  _npcLibPromise = fetchAndRunFile('/lib/library/npc/view.js').then(function() { return window.SWRPGLibrary; }, function() { _npcLibPromise = null; throw new Error('Failed to load NPC library'); });
  return _npcLibPromise;
}

// B-139 (ruling release-r7-bug-burndown ADDENDUM 426 §1/§4/§5, 428) — THE PLAYER'S LAZY PARTS. The build cuts this
// file (build/playerSplit.mjs) into app.js (first paint) + creator.js + sheet.js, and the vessel, OggDude and Modify files left
// player/index.html. A screen that needs a part waits for it: setScreen HOLDS the current screen until every part the
// next screen needs has run, so no loading look exists (§5); a cold load of such a screen loads its parts before the
// first render; after mount every part prefetches at idle. Each part's files run as classic scripts stamped with the build, so a
// cached app.js never runs a chunk from another deploy. The render sites of the five chunk roots also ask
// playerScreenReady, so a part that failed to load never throws; B-1705: that screen draws PartFailedPage or, when it can draw without the part, itself.
var PLAYER_PARTS = {
  creator: ['/player/creator.js'],                                    // FullCreator, QuickBuild, ImportOgg, ModifyHost
  sheet: ['/lib/shared/diceHub.js', '/player/sheet.js'],              // window.SWRPGDiceHub (the dice window, read by the sheet chunk), then CharacterSheet (in order)
  vessels: ['/lib/shared/vesselStore.js', '/lib/shared/vesselView.js'], // window.SWRPGVessels, SWRPGVesselView (in order)
  ogg: ['/lib/shared/oggImport.js', '/lib/shared/oggExport.js'],      // window.SWRPGOggImport, SWRPGOggExport
  modify: ['/lib/shared/charModify.js', '/lib/modify/view.js'],       // window.SWRPGModify, SWRPGModifyView (in order; f100-m13-reach-paper R-M13R-43)
};
// Every screen that reads a part (ADDENDUM 428: the vessel files on sheet, yard, store, import, custom; npc too —
// lib/library/npc/benchStore.js reads SWRPGVessels when the bench acts on a ship).
var PLAYER_SCREEN_PARTS = {
  custom: ['creator', 'vessels'], quickbuild: ['creator'], import: ['creator', 'vessels', 'ogg'],
  sheet: ['sheet', 'vessels'], yard: ['vessels'], store: ['vessels'], npc: ['vessels'], modify: ['creator', 'modify'],
};
var PLAYER_PART_STAMP = (typeof __HOLOCRON_BUILD__ !== 'undefined') ? __HOLOCRON_BUILD__ : '';
var _playerPartRun = {}, _playerFileRun = {}, _playerPartPromise = {}, _playerPartWake = null, _playerBootSilent = null;   // ADDENDUM 477: whichever fetch lands a part wakes a waiting screen
function playerPartReady(name) { return _playerPartRun[name] === true; }
function ensurePlayerPart(name) {
  if (_playerPartRun[name]) return Promise.resolve();
  if (_playerPartPromise[name]) return _playerPartPromise[name];
  // In order inside a part: vesselStore before vesselView, charModify before the page. A file that ran doesn't run again on a retry: a second run throws (creator, sheet) or replaces the one vessel state (548).
  _playerPartPromise[name] = PLAYER_PARTS[name].reduce(function(prev, src) {
    return prev.then(function() {
      if (_playerFileRun[src]) return null;
      return fetchAndRunFile(src, src + '?b=' + encodeURIComponent(PLAYER_PART_STAMP)).then(function() { _playerFileRun[src] = true; });
    });
  }, Promise.resolve()).then(function() { _playerPartRun[name] = true; if (_playerPartWake) _playerPartWake(); }, function(e) { _playerPartPromise[name] = null; throw e; });
  return _playerPartPromise[name];
}
function playerScreenReady(screen) { return (PLAYER_SCREEN_PARTS[screen] || []).every(playerPartReady); }
function ensurePlayerScreen(screen) { return Promise.all((PLAYER_SCREEN_PARTS[screen] || []).map(ensurePlayerPart)); }
// B-1705 (release-r7-bug-burndown ADDENDUM 511 Item 1): every part has landed or failed, so a part still on its way is never read as failed; rejects with the first failure.
function settlePlayerScreen(screen) {
  return Promise.all((PLAYER_SCREEN_PARTS[screen] || []).map(function(n) { return ensurePlayerPart(n).then(function() { return null; }, function(e) { return e; }); }))
    .then(function(rs) { var e = rs.filter(Boolean)[0]; if (e) throw e; });
}

// B-1705 (ADDENDUM 511 Item 2, D-470) — THE PARTS WITHOUT WHICH A SCREEN CANNOT DRAW. Only these earn PartFailedPage. store and npc draw without vessels, and so does
// sheet; modify falls to the sheet (ADDENDUM 475). The same facts as each screen's render gate; no gate is narrowed here.
var PLAYER_PAGE_PARTS = { import: ['creator', 'vessels', 'ogg'], custom: ['creator', 'vessels'], quickbuild: ['creator'], sheet: ['sheet'], yard: ['vessels'] };
function playerScreenCantDraw(screen) { return (PLAYER_PAGE_PARTS[screen] || []).some(function(n) { return !playerPartReady(n); }); }
var PART_FAILED_NAME = { import: 'Character files', custom: 'Custom Build', quickbuild: 'Guided Build', sheet: 'Character sheet', yard: 'Shipyard' };
var DOWNLOAD_FAILED_LINE = "That didn't download. Check your connection and tap again.";   // D-467's recorded words. The door keeps its own copy in DownloadFailedLine, one glyph apart (curly didn’t there, straight here); each matches its approved picture, so they stay two (f100-m13-build-card ADDENDUM 50)
// One page for every failed screen, in the first paint because it cannot live in the part that failed. The frames: D-470 (Artifact YFhKtyrKfaM15t1x6RCThr, version 1793937753-6d77).
