function SigAbilityJourney({ data, sheet, sheetSpecs, career, accent, availableXp, onBuy, onClose }) {
  var _sel = useState(null), selId = _sel[0], setSelId = _sel[1];
  var _pick = useState({}), treePick = _pick[0], setTreePick = _pick[1];
  var _dOpen = useState(false), setDetailOpen = _dOpen[1];
  var specs = data && data.specializations ? data.specializations : {};
  var treeName = function(id) { return (specs[id] && specs[id].name) || id || '—'; };
  var cols = function(c) { return (c || []).join(' and '); };
  var shelf = sigShelfOf(sheet, data, career, (sheetSpecs || []).map(function(s) { return s && s.id; }).filter(Boolean));
  var baseCost = shelf.length ? shelf[0].base.cost : 30;
  var rail = function(now) {
    return (
      <div className="sb-steps" data-testid="nsj-steps">
        {['Choose', 'Preview'].map(function(lab, i) {
          return <span className="sb-step" key={lab} data-state={i < now ? 'done' : i === now ? 'now' : 'next'} data-testid={'nsj-step-' + i}>{(i + 1) + ' · ' + lab}</span>;
        })}
      </div>);
  };
  var sel = selId ? shelf.filter(function(x) { return x.id === selId; })[0] : null;
  if (sel) {
    // ── STEP 2 · PREVIEW — the ability read whole: its attach tree (or F13's pick row), "To use it", its tree.
    var rec = sel.rec, cost = sel.base.cost, afford = cost <= availableXp, isHeld = sel.base.cost_status === 'inferred';
    var slug = groupIdSlug('Attach under'), two = sel.legal.length > 1;
    var tree = two ? (treePick[slug] || null) : sel.tree;
    var hypo = Object.assign({}, sheet, { signatureAbilities: (sheet.signatureAbilities || []).concat([{ id: sel.id, tree: tree || sel.tree, owned: ['0-0'] }]) });
    var act = sel.ok ? CharResolve.sigActivation(hypo, data, sel.id) : null;
    var terms = [];
    if (act && act.destiny && act.destiny.value) terms.push(act.destiny.value + ' Destiny');
    if (act && act.uses_per_session && act.uses_per_session.value != null) terms.push(act.uses_per_session.value === 1 ? 'once per session' : act.uses_per_session.value + ' times per session');
    var hw = sigHeldWords(rec);
    var line = isHeld ? ((rec.name || sel.id) + ' can’t be bought yet: its costs aren’t checked against ' + window.SWRPGSources.pageCite(hw.book, hw.page) + '.')
      : !sel.ok ? sel.problems.map(function(p) { return p.words; }).join(' ')
      : two && !tree ? 'Pick the tree to continue'
      : !afford ? ('This costs ' + cost + ' XP · you have ' + availableXp + '.')
      : ('Take ' + (rec.name || sel.id) + ' for ' + cost + ' XP.');
    var canBuy = sel.ok && !isHeld && afford && !!tree;
    return (
      <div className="sb-jwalk" data-testid="nsj-walk" data-walk="sig" data-step="preview">
        {rail(1)}
        <div className="sb-board sb-growth sb-jprev">
          <div className="sb-spine">
            <div className="hp-plate" data-pad="read" style={{ overflow: 'auto', minHeight: 0 }} data-testid="nsj-reading">
              <div className="hp-sechead" style={{ margin: '0 0 6px' }}><h2>{rec.name || sel.id}</h2><span className="hp-cite">{((career && career.name) || 'Career') + ' · signature ability'}</span></div>
              {two
                ? <div data-testid="sig-attach-pick">{fcSpeciesOptionGroups({ option_choices: [{ name: 'Attach under', options: sel.legal.map(function(id) { return { id: id, name: treeName(id) }; }) }] },
                    treePick, {}, {}, {}, function(s, id) { var n = {}; n[s] = id; setTreePick(n); })}</div>
                : <p className="sb-e-m" style={{ margin: '0 0 8px' }} data-testid="sig-attach">{'Attaches under ' + treeName(sel.tree) + ' at columns ' + cols(rec.attach && rec.attach.columns) + '.'}</p>}
              <div className="sb-grp" style={{ marginTop: 12 }}>To use it</div>
              <p className="sb-e-t" style={{ margin: '4px 0 6px', fontWeight: 600 }} data-testid="sig-terms">{terms.join(' · ')}</p>
            </div>
          </div>
          <div className="sb-stage">
            <div className="hp-plate" data-pad="data" style={{ flex: 1, minHeight: 0, overflow: 'auto' }}>
              <div className="hp-sechead" style={{ margin: '0 0 6px' }}><h2>The ability’s tree</h2></div>
              <div className="hp-treescroll" data-testid="nsj-tree">{h(DirectionalTree, { accent: accent, headPress: true, onDetailToggle: setDetailOpen, model: sigTreeModel(rec, { mode: 'read' }) })}</div>
            </div>
          </div>
        </div>
        <div className="sb-walkfoot">
          <span className="sb-e-t" style={{ flex: 1 }} data-testid="nsj-foot">{line}</span>
          <button type="button" className="hp-quiet" data-testid="nsj-back" onClick={function() { setSelId(null); setTreePick({}); }}>Back to the shelves</button>
          {isHeld
            ? <span className="sb-refuse" data-testid="nsj-refuse">COST UNVERIFIED</span>
            /* NAVIGATE first, THEN buy (NewSpecJourney's order): onBuy's onSheetChange re-renders and drops a nav queued after it */
            : <button type="button" className="hp-commit" data-testid="nsj-confirm" disabled={!canBuy}
                onClick={canBuy ? function() { var id = sel.id, t = tree; onClose(id, t); onBuy(id, t); } : undefined}>{'Confirm — ' + cost + ' XP'}</button>}
        </div>
      </div>);
  }
  // ── STEP 1 · CHOOSE — the career's abilities, each with its attach line, its price, its refusal in SIG_WORDS' words.
  return (
    <div className="sb-jwalk" data-testid="nsj-walk" data-walk="sig" data-step="choose">
      {rail(0)}
      <div className="hp-plate sb-jshelf" data-pad="read" data-testid="nsj-shelves">
        <p className="sb-e-t">{'A signature ability attaches under the bottom row of one of your career’s trees, where you own the talents it joins. Its base ability costs ' + baseCost + ' XP; its upgrades are bought on its tree, like talents.'}</p>
        <div className="sb-grp" style={{ marginTop: 12 }}>{'Career · ' + ((career && career.name) || '—')}<span>{shelf.length}</span></div>
        {shelf.map(function(x) {
          var c = x.base.cost, aff = c <= availableXp, why = x.ok ? null : x.problems.map(function(p) { return p.words; }).join(' ');
          return (
            <div className="sb-e sb-spec" key={x.id} data-sig-id={x.id} data-refused={(why || !aff) ? '1' : undefined}>
              <div className="sb-e-h">
                <span className="sb-e-n">{x.rec.name || x.id}</span>
                <span className="sb-e-m">{'attaches under ' + treeName(x.tree) + ' at columns ' + cols(x.rec.attach && x.rec.attach.columns)}</span>
                <span className="sb-spec-r">
                  {x.ok && !aff ? <span className="sb-refuse">{'NEED ' + c + ' XP'}</span> : <span className="sb-sk-cost">{c + ' XP'}</span>}
                  <button type="button" className="hp-quiet" data-testid={'nsj-card-' + x.id} aria-label={'Preview ' + (x.rec.name || x.id)}
                    onClick={function() { setTreePick({}); setSelId(x.id); }}>Preview</button>
                </span>
              </div>
              {why ? <p className="sb-e-t hp-why">{why}</p> : null}
            </div>);
        })}
      </div>
      <div className="sb-walkfoot">
        <button type="button" className="hp-quiet" data-testid="nsj-close" onClick={function() { onClose(); }}>Back to growth</button>
      </div>
    </div>);
}



/* ── Species free-choice skill grant — ONE home, and the home is the SHARED CORE ──────────────
   The species bonus-skill pick (Human 2×non-career, Geonosian 1×any, Klatooinian 1×non-career,
   Mandalorian-Human combat/knowledge, Xi'Dec Constructor Athletics-or-Mechanics). RAW REQUIRES it —
   "of their choice" (EotE p.48). The rule used to be implemented HERE, which made it the one species
   exception resolved inside the creator instead of beside the other option keys in `charResolve.js`
   — invisible to the exception census and at the mercy of every creator revision. The two functions
   below are now THIN WRAPPERS over `CharResolve.speciesChoiceGrants` / `speciesChoicePool`; the
   custom creator, Guided Build and the picker all still call these names, so no call site moved.
   The grant resolves from (species, picks) — the banked `speciesOption.picks` — never from a copied
   grant list. First-grant-only stays (B-37 latent: no species carries two record-level grants). */
function speciesChoiceGrantOf(speciesData, speciesOption) {
  var picks = (speciesOption && speciesOption.picks) || {};
  var g = window.CharResolve ? window.CharResolve.speciesChoiceGrants(speciesData, picks) : [];
  return g.length ? g[0] : null;
}
function speciesChoicePoolOf(grant, charbuild, careerStatusIds) {
  return window.CharResolve ? window.CharResolve.speciesChoicePool(grant, charbuild, careerStatusIds) : [];
}

/* ── FC Skill Picker ─────────────────────────────────── */

/* THE PICKER'S THREE AUTHORED STRINGS, HOISTED TO ONE HOME (B-750) — and the reason is that the PAPER
   face needs two of them from OUTSIDE the component.

   Frame AE draws the picker's act in the page's own act row (`hp-phoneact`), which is the HOST's
   furniture and not the picker's, so the confirm word has to be reachable from `QuickBuild`. Copying it
   there would be a second spelling of one word in one file — the defect `paperPocketBeat` was lifted out
   of `fcReviewCreditsPlate` to close one row ago (B-723). So the words live here and every face reads
   them: the dark `FCBottomAction`, the paper row's `hp-why`, and the paper act row.

   B-756 ITEM (1), RULED KEEP-AS-DRAWN (release-r7-bug-burndown ADDENDUM 85): the approved §D frames draw the act
   ABSENT until the pick completes (AC/AD; the act on AE), and the counter states what remains, so there is no press
   to refuse. `FCBottomAction` keeps `revealed={count === max}`; the 'SELECT n MORE' label it could never show is
   DELETED (the dead branch PRAXIS §6 names) — the act reads CONFIRM, the one word both faces print.

   ⚠ AND ONE COST, REPORTED RATHER THAN PAID SILENTLY: the lab board derives these two labels and the
   picks-used pair by reading JSX TEXT off this component's own lines (`qsg_build.py`'s `_PK_ACT` and
   `_PK_LIM`, which `raise SystemExit` when the shape moves). Hoisting them moves those lines. The board
   is PINNED at lab `18301f1f` and reads carry at a pinned sha, so nothing is broken today; a later lab
   lap that re-points at a newer carry will stop on those two reads and re-take them from here. That is
   the aging-figures rule doing its job — a hard stop instead of a stale number. */
var FC_PICK_CONFIRM = 'CONFIRM';
var FC_PICK_LIMIT_CHIP = 'PICKS USED';
var FC_PICK_LIMIT_WHY = 'Deselect one to take this instead';

function FCSkillPicker({ skills, skillNames, skillSheetKeys, selected, max, accent, otherSelected, preRankedSkills, currentRanks, rankCap, skillCaps, onToggle, onConfirm }) {
  // skills = array of CANONICAL skill ids to choose from
  // selected = array of currently selected canonical ids
  // otherSelected = array of ids already selected in another round (for overlap display)
  // skillSheetKeys bridges canonical id -> the legacy SHEET key used by the pools /
  // the vocab's skill descriptions / the species-grant state (3b migrates that keyspace).
  // currentRanks + rankCap (CR-RAW #1): sheetKey -> already-committed creation rank; a row at/over
  // the cap is disabled — RAW's "may not train above rank 2 at character creation" (EotE p.48).
  // B-55: ALL THREE creator instances now pass these. They used not to, and the gap shipped illegal
  // characters — species free rank + career pick + spec pick on one skill reached 3. The component
  // always supported the check; two of three call sites simply never armed it.
  // skillCaps = per-skill override (B-19: Corellian Piloting -> 3, Suns of Fortune p.95), the SAME
  // source and `caps[key] || CREATION_CAP` idiom FCSkillBuyList uses. Without it a flat cap of 2
  // would BLOCK a legal rank-3 pick — the overcorrection R-DT29-1 exists to prevent.
  // B-18 self-heal (defense in depth): count ONLY selections that are actually OFFERED here. A stale
  // id left over from a prior subject (a career/spec change) is never in `skills`, so it can't count
  // toward `max` — no "4 OF 3" lockout. Deselecting real rows stays live; the honest count gates CONFIRM.
  var _offered = {};
  (skills || []).forEach(function(id) { _offered[id] = true; });
  var count = (selected || []).filter(function(id) { return _offered[id]; }).length;
  var charAbbr = { BR: 'Brawn', AG: 'Agility', INT: 'Intellect', CUN: 'Cunning', WIL: 'Willpower', PR: 'Presence' };

  /* ── ONE ROW, ONE SET OF FACTS (B-750) — extracted because there are now TWO faces and a row's
     state is BEHAVIOUR, not decoration. `atCap` and `canSelect` are the RAW creation cap (EotE p.48)
     and the pick limit; a paper branch that recomputed them beside the dark one is the shape that
     ships two answers to one question. Not one term changed in the lift — the dark map below reads
     exactly these values, in this order, and `smoke_skills_transplant` / `smoke_b14_guided_species`
     drive the dark picker to prove the lift inert. */
  function rowFacts(sk) {
    var sheetKey = (skillSheetKeys && skillSheetKeys[sk]) || sk;
    var curRank = currentRanks ? (currentRanks[sheetKey] || 0) : 0;
    var isSelected = selected.indexOf(sk) >= 0;
    var effCap = (skillCaps && skillCaps[sheetKey]) || rankCap;
    var atCap = effCap != null && curRank >= effCap && !isSelected;
    return {
      sheetKey: sheetKey,
      name: (skillNames && skillNames[sk]) || sk,
      charKey: skillBaseAbbr(sheetKey) || '?',
      isSelected: isSelected,
      isOtherSelected: !!(otherSelected && otherSelected.indexOf(sk) >= 0),
      preRank: preRankedSkills ? (preRankedSkills[sheetKey] || 0) : 0,
      curRank: curRank,
      effCap: effCap,
      atCap: atCap,
      canSelect: !atCap && (isSelected || count < max),
      desc: skillDescFor(sheetKey),
    };
  }

  /* THE COUNTER, ONE HOME AND ONE SENTENCE. It is the only visible statement of what remains (see
     the B-756 (1) note above `FC_PICK_CONFIRM`), so the two faces must not be able to print two different
     ones. Left as a JSX TEXT LINE rather than a string because that is what it is on both faces — and
     because the lab board derives the counter's FORMAT by matching that line's shape, so a string
     would read to it as a reworded counter. */
  var _pickCounter = (
    <React.Fragment>
      {count} OF {max} SELECTED
    </React.Fragment>
  );

  /* ══ GUIDED'S GRANT PICK ON PAPER (B-750; frames AC · AD · AE of lab `18301f1f` §D, Jason-approved
     2026-09-21) ══════════════════════════════════════════════════════════════════════════════════
     R-QSG-3's device on the one component Guided and the full creator SHARE: the same component, the
     same state, the same writers, the same testids, and an `if (paper)` branch drawing the board's
     markup — `SellSheet`'s pattern (and `VesselSheet`'s, until the Ship Yard's S5 flip deleted it), not a second kernel and not a player-side copy.
     FOUR MOUNTS EXIST and this branch lights ONE: Guided's. The creator's three keep the dark face
     until their own row draws them.

     THE ROW IS THE REGISTER ROW, the object this board and the creator board already agree on: one
     strong selection state (a red spine and the designation in red — no checkbox, no tag, no rank
     chip, which `build.py`'s `skill_row` deleted from this exact subject), the reason line under a row
     that cannot be taken, and the tab carrying the row's own mark. THE TWO REFUSAL INKS ARE THE KIT'S
     AND MEAN DIFFERENT THINGS (`holocron.css` §14): red is a price you cannot meet YET, ink-2 is a
     limit you have REACHED. Picks-used is the second — nothing clears it but taking a pick back — so
     the row takes `data-limit="1"`, whose ink-2 spine and dashed tab the kit already draws.

     THE DESCRIPTION IS ON EVERY ROW, which is B-79/B-80's whole subject: the shipped picker used to
     reveal it only once a row was selected, a closed chain that left exactly half the list unreadable
     at the moment of deciding. It is unconditional in the product now, so it is unconditional here.

     THE COLUMN COUNT IS A CONSEQUENCE OF THE READING MEASURE, never a band — `qsg.css`'s `.gb-pick`
     carries the app's own `repeat(auto-fit, minmax(min(--desk-prose-max, 100%), 1fr))`, so the phone
     and the desk are ONE drawing asked the same question. Inside GUIDED the answer is always ONE
     column, because `QB_STEP_COLUMN_MAX` is `--desk-read-max` and two measures plus a gutter do not
     fit in it; that is arithmetic between three tokens and `qsg.css` says so where the rule lives.

     THREE ROW STATES ARE DRAWN AND THREE ANNOTATIONS ARE NOT, and the three that are not are
     STRUCTURALLY UNREACHABLE AT THIS MOUNT rather than skipped: Guided passes `otherSelected={[]}` and
     no `preRankedSkills`, so the CAREER and SPECIES chips belong to the creator's three mounts; and
     at-cap cannot occur, because every rank Guided has committed by step 3 is a career skill and a
     non-career pool excludes them. Their BEHAVIOUR is untouched — `atCap` still closes a row through
     the shared `rowFacts` above — but no paper ANNOTATION is invented for a state no approved frame
     draws (R-MU1). `smoke_qsg_transplant` asserts all three unreachable from the registries; when the
     creator's mounts take this face, their row draws them and their frames say how. */
  return (
    <div className="gb-pickwrap">
      <div className="hp-none gb-pickcount" data-tour-id="p-custom-skills-counter"
        role="status" aria-live="polite">{_pickCounter}</div>
      <div className="hp-plate" data-pad="bleed">
        <div className="gb-pick" data-skill-list="1">
          {skills.map(function (sk, idx) {
            var f = rowFacts(sk);
            var limit = !f.isSelected && !f.atCap && !f.canSelect;
            return (
              <button type="button" key={sk} className="hp-row gb-pickrow" data-noplate="1"
                data-skill-row={sk}
                data-tour-id={idx === 0 ? 'p-custom-skills-card' : undefined}
                data-selected={f.isSelected ? '1' : undefined}
                data-limit={limit ? '1' : undefined}
                aria-pressed={f.isSelected}
                aria-label={(f.isSelected ? 'Selected' : 'Not selected') + ': ' + f.name
                            + ' (' + (charAbbr[f.charKey] || f.charKey) + ')'}
                onClick={function () { if (f.canSelect || f.isSelected) onToggle(sk); }}>
                <span className="hp-row-body">
                  <span className="hp-row-desig">{f.name}</span>
                  {/* THE CHARACTERISTIC IS SPELLED, not abbreviated — `build.py`'s B-427: three
                      different abbreviation tables for six words lived on this board's neighbours
                      and two of them disagreed. The word is the component's OWN `charAbbr`, cased
                      up; no second table. */}
                  <span className="hp-none" data-tour-id={idx === 0 ? 'p-custom-skills-char' : undefined}>
                    {(charAbbr[f.charKey] || f.charKey).toUpperCase()}</span>
                  {f.desc ? <span className="gb-d" data-skill-desc={sk}>{f.desc}</span> : null}
                  {limit ? (
                    <span className="hp-why">{FC_PICK_LIMIT_CHIP}{' · '}{FC_PICK_LIMIT_WHY}</span>
                  ) : null}
                </span>
                <span className="hp-row-tab">{'›'}</span>
              </button>);
          })}
        </div>
      </div>
    </div>
  );
}

/* ── Talent-choice skill picker (B-181) ──────────────────────────────────────────────────────
   The pick is INSIDE the purchase (R-TCPK-1): choosing which skills a choice-talent (Well Rounded,
   Well Read) makes into career skills happens in one focused overlay, atomically with the buy. Two
   MODES: 'buy' (creation / advancement — the header shows the XP cost and CONFIRM completes the
   purchase) and 'choose' (the legacy migration, ruling talent-choice-legacy-migration §8 — the
   talent is already OWNED, so no XP is shown or charged and CONFIRM only files the choice). A reading
   strip (R-TCPK-5..8) between the chips and the pinned confirm bar shows any focused skill's
   description, its characteristic in the standing colour (FC_CHAR_COLORS) and the page cite verbatim
   — definitions come through the ONE shared CharResolve.skillDescription (skillDescFor), never a
   second copy (C-SDS-1). The strip GROWS TO FIT (Jason override of R-TCPK-6's fixed-height scroll);
   the confirm bar is PINNED so a taller strip never shifts it. Pool-parametric via speciesChoicePoolOf
   (any / knowledge / …) — the SAME resolver the species/spec pickers use, which throws on an undefined
   category so data drift is loud, not a silent over-grant. Already-career skills in the pool are shown
   for context but disabled (making an already-career skill a career skill grants nothing). Wired by
   both mounts: the creator talent step and the sheet ADVANCEMENT tree. */
// B-1825 (ADDENDUM 631): the picker's door is gone when it closes — the tree's sheet that raised it closed on the buy — so a
// cancel hands focus back to the talent's cell, the door the walk began at (its head on the phone, its tab at the desk).
function talentCellFocus(row, col) {
  var c = document.querySelector('[data-testid="talent-cell-' + row + '-' + col + '"]');
  var b = c && [c.querySelector('.hp-head[role=button]'), c.querySelector('button.hp-tab'), c.querySelector('button, [role=button]')]
    .filter(function(x) { return x && x.getClientRects().length; })[0];
  if (b) b.focus();
}
function TalentSkillChoicePicker({ talentName, grants, charbuild, careerStatusIds, cost, mode, initialPicks, accent, onConfirm, onCancel }) {
  var _sel = useState(function() { return (initialPicks || []).slice(); });
  var selected = _sel[0], setSelected = _sel[1];
  var _foc = useState(null), focused = _foc[0], setFocused = _foc[1];
  // B-1825/B-1826 (ADDENDUM 631): the picker holds focus, and Escape is the scrim's close, CANCEL
  var holdRef = useRef(null);
  window.SWRPGUI.useHoldFocus(holdRef, true);
  window.SWRPGUI.useEscape(true, onCancel);
  var desktop = useLayoutMode() === 'desktop';
  var names = (charbuild && charbuild.skillNames) || {};
  var groups = (charbuild && charbuild.skillGroups) || {};
  var sheetKeys = (charbuild && charbuild.skillSheetKeys) || {};
  var cites = (charbuild && charbuild.skillCites) || {};
  // The pool = the union of every grant's pool, each grant resolved through the SAME species picker
  // core (one mechanism; unresolved category throws upstream). Deduped, order preserved.
  var pool = React.useMemo(function() {
    var out = [], seen = {};
    (grants || []).forEach(function(g) {
      speciesChoicePoolOf(g, charbuild, careerStatusIds).forEach(function(id) {
        if (!seen[id]) { seen[id] = true; out.push(id); }
      });
    });
    return out;
  }, [grants, charbuild, careerStatusIds]);
  var max = (grants || []).reduce(function(n, g) { return n + (Number(g.count) || 0); }, 0);
  // Novice-first arrangement: bucket the pool by category (general/combat/knowledge/social).
  var byGroup = React.useMemo(function() {
    var order = ['general', 'combat', 'knowledge', 'social'], buckets = {};
    pool.forEach(function(id) { var g = groups[id] || 'general'; (buckets[g] = buckets[g] || []).push(id); });
    return order.filter(function(g) { return buckets[g]; }).map(function(g) { return { group: g, ids: buckets[g] }; });
  }, [pool, groups]);
  function toggle(id) {
    setFocused(id);
    setSelected(function(prev) {
      if (prev.indexOf(id) >= 0) return prev.filter(function(k) { return k !== id; });
      if (prev.length >= max) return prev;                // honest cap at the grant count
      return prev.concat([id]);
    });
  }
  // The strip resolves the focused skill, else the most-recent selection, else the prompt.
  var stripId = focused || (selected.length ? selected[selected.length - 1] : null);
  var strip = null;
  if (stripId) {
    var sk = sheetKeys[stripId] || stripId;
    var abbr = skillBaseAbbr(sk, charbuild);
    var word = ({ BR: 'brawn', AG: 'agility', INT: 'intellect', CUN: 'cunning', WIL: 'willpower', PR: 'presence' })[abbr] || '';
    strip = { name: names[stripId] || stripId, desc: skillDescFor(sk), cite: cites[sk] || '', abbr: abbr, hue: FC_CHAR_COLORS[word] || accent };
  }
  var canConfirm = max > 0 && selected.length === max;
  var GROUP_LABEL = { general: 'GENERAL', combat: 'COMBAT', knowledge: 'KNOWLEDGE', social: 'SOCIAL' };
  return (
    <div role="dialog" aria-modal="true" aria-label={(talentName || 'Talent') + ' — choose your skills'} ref={holdRef}
      style={{ position: 'fixed', inset: 0, zIndex: 4000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '16px' }}>
      <div onClick={onCancel} style={{ position: 'absolute', inset: 0, background: 'rgba(4,6,9,0.72)', backdropFilter: 'blur(2px)' }} />
      <div style={{ position: 'relative', zIndex: 2, width: '100%', maxWidth: desktop ? '900px' : '560px',
        maxHeight: '90vh', display: 'flex', flexDirection: 'column',
        border: '1px solid ' + accent + '52', borderRadius: '14px', background: '#0c111b',
        boxShadow: '0 24px 60px rgba(0,0,0,0.6)', overflow: 'hidden' }}>
        {/* Header — talent + count + (buy mode) the XP cost */}
        <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: '10px', padding: '14px 16px', borderBottom: '1px solid rgba(255,255,255,0.1)', flexShrink: 0 }}>
          <div style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 'var(--fs-sm)', color: '#fff', letterSpacing: '0.03em' }}>
            {(talentName || 'TALENT').toUpperCase()} — CHOOSE YOUR SKILLS
            {mode === 'buy' && cost != null && <span style={{ fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-xs)', color: 'var(--text-caution)', marginLeft: '10px' }}>{cost + ' XP'}</span>}
          </div>
          <div role="status" aria-live="polite" style={{ fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-xs)', letterSpacing: '0.12em', color: 'var(--text-caution)', flexShrink: 0 }}>{selected.length} OF {max}</div>
        </div>
        {/* Binding line — the permanence, stated (R-TCPK-2, C-B181-1) */}
        <div style={{ fontSize: 'var(--fs-xs)', lineHeight: 1.5, color: 'rgba(255,255,255,0.74)', padding: '11px 16px', background: 'rgba(255,200,87,0.05)', borderBottom: '1px solid rgba(255,255,255,0.07)', flexShrink: 0 }}>
          {"This choice is bound to this purchase. Refund the talent and the choice goes with it; it can't be changed while you own the rank."}
        </div>
        {/* Main — chips + reading strip; scrolls, footer stays pinned */}
        <div style={{ display: 'flex', flexDirection: desktop ? 'row' : 'column', alignItems: 'stretch', overflowY: 'auto', flex: 1, minHeight: 0 }}>
          <div style={{ flex: desktop ? 1 : 'none', minWidth: 0, padding: '12px 16px' }}>
            {byGroup.map(function(bg) {
              return (
                <div key={bg.group} style={{ marginBottom: '12px' }}>
                  <div style={{ fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-2xs)', letterSpacing: '0.16em', color: 'rgba(255,255,255,0.42)', marginBottom: '7px' }}>{GROUP_LABEL[bg.group] || bg.group.toUpperCase()}</div>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '7px' }}>
                    {bg.ids.map(function(id) {
                      var isCareer = !!(careerStatusIds && careerStatusIds[id]);
                      var isChosen = selected.indexOf(id) >= 0;
                      var isFocused = focused === id;
                      var atCap = !isChosen && selected.length >= max;
                      var sk2 = sheetKeys[id] || id;
                      return (
                        <button key={id} type="button" data-skill-chip={id}
                          onClick={function() { toggle(id); }}
                          onFocus={function() { setFocused(id); }}
                          aria-pressed={isChosen}
                          aria-label={(isChosen ? 'Selected' + (isCareer ? ' (already career)' : '') : (isCareer ? 'Already a career skill' : 'Not selected')) + ': ' + (names[id] || id)}
                          style={{
                            display: 'inline-flex', alignItems: 'center', gap: '6px', minHeight: '44px', padding: '8px 12px', borderRadius: '9px',
                            fontFamily: 'var(--font-body)', fontSize: 'var(--fs-sm)', textAlign: 'left', cursor: 'pointer',
                            border: '1px solid ' + (isChosen ? accent : isFocused ? 'var(--text-info)' : 'rgba(255,255,255,0.16)'),
                            background: isChosen ? accent + '28' : 'rgba(255,255,255,0.03)',
                            color: isChosen ? '#fff' : isCareer ? 'rgba(255,255,255,0.4)' : 'rgba(255,255,255,0.86)',
                            borderStyle: isCareer ? 'dashed' : 'solid',
                            boxShadow: isFocused ? '0 0 0 2px rgba(126,196,255,0.5)' : isChosen ? '0 0 14px -4px ' + accent : 'none',
                            opacity: atCap ? 0.55 : 1,
                          }}>
                          {isChosen && <span style={{ color: accent, fontWeight: 700 }} aria-hidden="true">✓</span>}
                          <span>{names[id] || id}</span>
                          <span style={{ fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-2xs)', letterSpacing: '0.08em', color: 'rgba(255,255,255,0.42)' }}>{isCareer ? 'CAREER' : skillBaseAbbr(sk2, charbuild)}</span>
                        </button>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
          {/* Reading strip — follows focus, rests on the selection, prompts when empty */}
          <div style={{ background: 'rgba(126,196,255,0.04)',
            borderTop: desktop ? 'none' : '1px solid rgba(255,255,255,0.1)',
            borderLeft: desktop ? '1px solid rgba(255,255,255,0.1)' : 'none',
            width: desktop ? '318px' : 'auto', flexShrink: 0, alignSelf: 'stretch' }}>
            <div style={{ fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-2xs)', letterSpacing: '0.18em', color: 'rgba(126,196,255,0.7)', padding: '9px 16px 5px' }}>SKILL REFERENCE</div>
            <div style={{ padding: '0 16px 14px' }}>
              {strip && (
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '9px', marginBottom: '4px' }}>
                    <span style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 'var(--fs-sm)', color: '#fff' }}>{strip.name}</span>
                    {strip.abbr && <span style={{ fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-2xs)', letterSpacing: '0.1em', border: '1px solid ' + strip.hue, color: strip.hue, borderRadius: '4px', padding: '1px 6px' }}>{strip.abbr}</span>}
                  </div>
                  <div style={{ fontSize: 'var(--fs-sm)', lineHeight: 1.45, color: 'rgba(255,255,255,0.8)' }}>{strip.desc}</div>
                  {strip.cite && <div style={{ fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-2xs)', color: 'var(--text-faint)', marginTop: '5px' }}>{strip.cite}</div>}
                </div>
              )}
            </div>
          </div>
        </div>
        {/* Footer — PINNED; CONFIRM enabled only at exactly the grant count */}
        <div style={{ borderTop: '1px solid rgba(255,255,255,0.1)', padding: '12px 16px', display: 'flex', gap: '10px', justifyContent: 'flex-end', flexWrap: 'wrap', flexShrink: 0,
          flexDirection: desktop ? 'row' : 'column-reverse' }}>
          <button type="button" onClick={onCancel} style={{ minHeight: '46px', padding: '0 18px', borderRadius: '10px', fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 'var(--fs-xs)', letterSpacing: '0.04em', background: 'transparent', border: '1px solid rgba(255,255,255,0.2)', color: 'rgba(255,255,255,0.8)', cursor: 'pointer', width: desktop ? 'auto' : '100%' }}>CANCEL</button>
          <button type="button" disabled={!canConfirm} onClick={function() { if (canConfirm) onConfirm(selected.slice()); }}
            style={{ minHeight: '46px', padding: '0 22px', borderRadius: '10px', fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 'var(--fs-xs)', letterSpacing: '0.04em',
              background: canConfirm ? accent : 'rgba(255,255,255,0.07)', color: canConfirm ? '#04121f' : 'rgba(255,255,255,0.4)',
              border: 'none', cursor: canConfirm ? 'pointer' : 'default', boxShadow: canConfirm ? '0 0 26px -8px ' + accent : 'none', width: desktop ? 'auto' : '100%' }}>
            {canConfirm ? 'CONFIRM' : 'SELECT ' + (max - selected.length) + ' MORE'}
          </button>
        </div>
      </div>
    </div>
  );
}


/* ── FC Creation Skill Purchase (CR-RAW #2) ──────────────
   Buy skill ranks with starting XP (EotE p.35/p.102): career skills 5 × the new rank,
   non-career +5 more, nothing above rank 2 at creation (p.48). Costs come from THE shared
   CharResolve.skillRankCost (§3.2 one-pricing-path); career STATUS is the career ∪ spec
   union (RAW: spec skills ARE career skills, p.44/p.102 — the sheet's R-CSK1 rule).
   Single-tap buy: refund (−) makes it reversible here, unlike the sheet's permanent
   post-creation buys (which keep their two-tap arm).
   DESIGN (Jason 2026-07-11 — replicate the creator's novice-first information design):
   rows are the FCSkillPicker card idiom verbatim — char-hue color bar, tap-to-expand
   the registry's plain-language explanations, the CAREER chip users learned in the free-picks
   screens (here it carries "why this one is cheaper"). The list is grouped BY CHARACTERISTIC
   (header = the characteristic's name in its hue + the character's current value) so the
   color system carries MEANING: you roll characteristic + skill, and the novice can see
   which stat feeds each skill before spending. */


/* ── FC Species-penalty buyout ────────────────────────────
   Ruling `species-followups-creator-moments` §3 (R-SFC-1/2/3) · price + census amended by
   `creation-buyout-count-and-price` (R-CBC-1/2/4) · mockup Docs/mockups/creation-buyout.html.

   35 species records print a sentence offering to remove a penalty for XP at character creation,
   and until now there was nowhere to pay it. This is where the player acts on it. It lives in the
   XP step and NOT on the species page, which is where the sentence is printed: a player choosing a
   species has not met the XP economy yet, so "is this worth 10?" has nothing to be weighed against.
   The printed sentence stays where it is and does the advertising.

   NOTHING HERE IS KEYED TO A NAME OR A PRICE. The offers arrive resolved from the FIELD
   (`CharResolve.speciesBuyoutOffers` → `buyout_xp`), which is what makes this correct for all four
   ability names on the shelf (Primitive, Easily Distracted, Small Comforts, Social Anxiety), for
   both prices (10 and 5), and for the one carrier that exists only on a picked subspecies. A
   hard-coded 10 charges Roonan and Toong double; a name match misses four records. */



/* ── FC Narrative Mechanic ────────────────────────────── */





/* THE LAYERED MORALITY, BUILT IN ONE PLACE (R-MEP-1; lifted out of `FCMechanicStep`'s body by
   `build-phone-mechanic` so the confirm handler and the render read the SAME builder — two
   expressions of one save shape is the second-resolution-path defect PRAXIS §5 names, and the
   confirm now needs the object before the render's `var` is reached).

   Locked at 50, no credit/XP trade through it (cap guard by construction — this track contributes
   0 to the +2,500cr/+10XP creation cap). `descriptor` carries the strength; `descriptorWeak` is
   written ONLY when the player departed from the book's pairing, and is ABSENT otherwise — absence
   is what means "the pairing", so old saves and undeparted new ones read identically. Built
   through the shared write rule so the absence is not re-implemented at the one site that can get
   it wrong. NOTHING ABOUT THE SHAPE MOVED: same keys, same defaults, same patch call. */
function fcBuildMoralityLayer(gameData, moralStrength, moralWeak) {
  var layer = { type: 'morality', descriptor: moralStrength || '', baseValue: 50,
    finalValue: 50, xpAdjustment: 0, creditAdjustment: 0, tradeIds: [], entries: [] };
  if (moralStrength && moralWeak) {
    var _msObj = (((gameData.narrativeMechanics || {}).morPairs || {}).strengths || [])
      .filter(function(s) { return s.key === moralStrength; })[0];
    var _patch = CharResolve.moralityWeakPatch(_msObj, moralWeak);
    if (_patch.descriptorWeak) layer.descriptorWeak = _patch.descriptorWeak;
  }
  return layer;
}

function FCMechanicStep({ savedMechanic, gameLine, gameData, partySize, setPartySize, accent, onComplete, hasForce,
  /* THE TRANSPLANT'S SHELL PROPS. The step owned none of these before, because the
     shared creator header drew them; the board's frame carries its own bar, wave and
     rail, so the step is handed what it must print. Absent on the legacy path, which
     is why every one of them is read only inside the `transplanted` branch. */
  band, stepIndex, stepTotal, steps, stepLabels, soFar, onBack, onJump,
  /* `stepReached` was PASSED by the transplanted mount and never destructured — the wide sheet's
     wave computes `data-done` off `stepIndex` alone and could not tell reached from passed. The
     phone shell reads it (`FCPhoneShell`: `stepReached == null ? stepIndex : stepReached`), so the
     prop has to arrive with a name here or the phone wave silently falls back to the cursor —
     A27-3's exact defect, which is why the fallback is not left to do the work. */
  stepReached,
  xpPool, xpRemaining, xpPoolWithMechanic }) {
  var _useMD = useState(null), mechDescriptor = _useMD[0], setMechDescriptor = _useMD[1];
  var _useMT = useState([]), selectedTradeIds = _useMT[0], setSelectedTradeIds = _useMT[1];
  // BOOKS-1c Part B (mode c, fad p.337-338): a Force element in an Obligation/Duty campaign
  // ALSO attaches Morality. We stash the primary mechanic and offer a one-tap attach/decline
  // BEFORE completing, so both tracks reach the sheet (populate-two-of-three).
  // THE REGISTER'S SEARCH — the board draws a search plate over the type list, and 41/49 rows is
  // a list you search rather than scroll. The shipped step had none because its list lived behind
  // a sub-view. Lives here with the other state so the transplanted return below stays hook-free.
  var _useQ = useState(''), mechQuery = _useQ[0], setMechQuery = _useQ[1];
  // THE TWO-TRACK PAIR (R-MEP-1). Its own state, because in the two-track case the MAIN register is
  // the Obligation — `mechDescriptor` is spoken for. `moralWeak` is null while the player is on the
  // book's pairing and holds a key only once they depart, which is exactly what gets persisted.
  var _useMS = useState(null), moralStrength = _useMS[0], setMoralStrength = _useMS[1];
  var _useMW = useState(null), moralWeak = _useMW[0], setMoralWeak = _useMW[1];
  var _useSQ = useState(''), strQuery = _useSQ[0], setStrQuery = _useSQ[1];
  var _useWQ = useState(''), weakQuery = _useWQ[0], setWeakQuery = _useWQ[1];
  // THE MORALITY LAYER'S ANSWER, HELD AS STATE INSTEAD OF ASKED ON A FOURTH PAGE (R-PMeC-2).
  // Mode c (fad p.338) attaches Morality to a Force-sensitive character in an Obligation or Duty
  // campaign, and the shipped flow asked "keep it, or ignore Morality and Conflict entirely?" on a
  // `moralityLayer` sub-view reached AFTER the commit. The sheet never drew that sub-view, so pressing
  // the commit as a two-track character set a sub-view nothing draws and the step did not advance.
  // MEASURED, not inferred: seeded Wookiee / Hired Gun / Force Sensitive Exile at 1920, Bounty and
  // Bravery chosen, commit pressed, `data-creator-step` still `mechanic` afterwards. A dead end is
  // not shippable (C-MU-4, the rule that kept the refund control against the board's silence).
  // KEPT IS THE DEFAULT, because it is the RAW default the frames' own two-track lead states
  // ("your own Morality rides alongside because your character is Force-sensitive") and the shipped
  // copy's advice ("Most Force-sensitive heroes should keep it"). The phone draws the toggle on the
  // Morality track card; the wide sheet's frame draws no control, so at that band the default is
  // what completes — which unstrands it without adding an object the approved frame does not draw.
  var _useMK = useState(true), moralityKept = _useMK[0], setMoralityKept = _useMK[1];

  var mechType = mechanicForLine(gameLine);                          // B-107: one home
  var mechConfig = gameData.narrativeMechanics.config;
  var mechData = mechConfig.mechanics[mechType];
  var trades = mechData && mechData.tradeOptions ? mechData.tradeOptions.choices : [];

  // Get types list
  // D-C2-4 — THE REGISTER SHOWS THE SHELF'S SET. These three lists were the only creator registers
  // that ignored the bookshelf entirely: measured, every entry reached the screen whatever was
  // enabled (41/41 obligation, 49/49 duty, 39/39 morality). Not a filter that was wrong — a filter
  // that was never called. `fcFilterActive` is the creator's one home for the question and it is
  // NOT era-gated here: a campaign mechanic belongs to its line by definition, so gating it again
  // by era would refuse a player their own line's Obligations.
  // UNSOURCED ENTRIES STAY (shipped law, and `isActiveWith`'s first line): 8 obligation, 2 duty and
  // 1 morality record carry no book and are always offered.
  var types = [];
  if (mechType === 'obligation') {
    types = fcFilterActive(gameData.narrativeMechanics.oblTypes.items || [], null, false);
  } else if (mechType === 'duty') {
    types = fcFilterActive(gameData.narrativeMechanics.dutyTypes.items || [], null, false);
  } else if (mechType === 'morality') {
    // B-67(b): THE PAIRING IS THE MECHANIC, and it was invisible until after the choice.
    // The step asks a player to choose their emotional pair and then showed them single words —
    // Bravery, Love, Caution — while the shadow each one carries (Anger, Jealousy, Fear) stayed
    // hidden until the detail. You cannot weigh Bravery against Compassion without knowing you are
    // also choosing between Anger and Hatred. Resolved BY `weakKey` from `pairing`'s own mapping,
    // never by list position (see B-117, one path over, where position mispaired 39 of 39).
    var _mw = {};
    (gameData.narrativeMechanics.morPairs.weaknesses || []).forEach(function(w) { _mw[w.key] = w; });
    // D-C2-4 applies to the STRENGTH — the thing the player picks. The weakness is not filtered
    // separately: it is not chosen, it is the shadow `weakKey` names, and gating it independently
    // could pair an offered strength with a hidden weakness and print a blank shadow.
    types = fcFilterActive(gameData.narrativeMechanics.morPairs.strengths || [], null, false)
      .map(function(s) {
        var w = _mw[s.weakKey];
        // The DESCRIPTION rides along with the name, because the board's own morality frame
        // reads BOTH halves of the pair on the spend screen and the shadow's reading was the
        // half we were not carrying. Same `weakKey` mapping, same map step — a second lookup
        // for the same fact is the second-path defect by name (PRAXIS §5).
        return w ? Object.assign({}, s, { pairedWeaknessName: w.name,
                                          pairedWeaknessDesc: w.description || '' }) : s;
      });
  }

  // ── A3-2: THE OLD-DATA PATH ────────────────────────────────────────────────────────────────
  // A player who chose an Obligation from a book they have since switched off must not find their
  // own character's answer missing. Measured before this existed: the record survived in the draft
  // (`descriptor: "DISGRACED"`) and nothing blocked — but the register showed 33 of 41 and the
  // player's own pick was simply GONE from the screen. Surviving in storage is not the same as
  // surviving to the eye.
  //
  // SO THE SAVED PICK IS RE-ADMITTED, and only it: the filter still governs everything a player
  // has NOT chosen, so switching a book off still removes its OFFERS. `_fromRetired` marks the
  // row so the surface can say WHY it is here — the book label is the honest part, not decoration.
  // Never deleted, never blocking, and never silently re-enabling a book's whole table.
  var _savedKey = savedMechanic && savedMechanic.type === mechType ? savedMechanic.descriptor : null;
  if (_savedKey && !types.some(function(t) { return t.key === _savedKey; })) {
    var _all = mechType === 'obligation' ? (gameData.narrativeMechanics.oblTypes.items || [])
             : mechType === 'duty' ? (gameData.narrativeMechanics.dutyTypes.items || [])
             : (gameData.narrativeMechanics.morPairs.strengths || []);
    var _kept = _all.filter(function(t) { return t.key === _savedKey; })[0];
    if (_kept) types = types.concat([Object.assign({}, _kept, { _fromRetired: true })]);
  }

  // Compute base value from party size
  var baseValue = 10;
  if (mechData && mechData.startingValueRule) {
    var rule = mechData.startingValueRule;
    if (rule.basis === 'partySize' && rule.valuesByPartySize) {
      var found = rule.valuesByPartySize.find(function(v) { return String(v.partySize) === String(partySize) || (v.partySize === '6+' && partySize >= 6); });
      if (found) baseValue = found.startingValuePerPC;
    } else if (rule.basis === 'fixed') {
      baseValue = rule.startingValue || 50;
    }
  }

  var descriptorName = '';
  if (mechDescriptor) {
    var typeObj = types.find(function(t) { return t.key === mechDescriptor; });
    descriptorName = typeObj ? typeObj.name : mechDescriptor;
  }

  var tradeMode = (mechData && mechData.tradeOptions && mechData.tradeOptions.mode) || 'multi';
  var handleToggleTrade = useCallback(function(id) {
    setSelectedTradeIds(function(prev) {
      // UXQP-20 (RAW, fad p.52): single_pick = radio semantics — choose ONE or none.
      if (tradeMode === 'single_pick') {
        return prev.indexOf(id) >= 0 ? [] : [id];
      }
      return prev.indexOf(id) >= 0 ? prev.filter(function(k) { return k !== id; }) : prev.concat([id]);
    });
  }, [tradeMode]);

  var handleConfirm = useCallback(function() {
    var mech = computeMechanic(mechType, baseValue, mechDescriptor, selectedTradeIds, mechConfig);
    // T2-C: computeMechanic returns null when trades exceed the cap — the panel disables those
    // combos now, but if one slips through, keep the mechanic WITHOUT trades rather than
    // silently dropping the whole mechanic (the old failure).
    if (!mech && selectedTradeIds.length) {
      console.error('[mechanic] trade cap violated at confirm — keeping the mechanic, dropping trades');
      mech = computeMechanic(mechType, baseValue, mechDescriptor, [], mechConfig);
    }
    // mode c: Force character in an Obligation/Duty campaign → the Morality layer rides along.
    if (hasForce && (mechType === 'obligation' || mechType === 'duty')) {
      // THE ANSWER IS HERE, not on a sub-view: the old `moralityLayer` sub-view was never drawn on
      // the sheet, so setting it left the step showing the same screen and going nowhere. Measured
      // at 1920 on a seeded Wookiee / Hired Gun / Force Sensitive Exile with Bounty and Bravery
      // chosen: commit pressed, `data-creator-step` still `mechanic`. `moralityKept` carries the answer instead —
      // the phone draws its toggle on the Morality track card (R-PMeC-2), and at mid/wide, where
      // the approved frame draws no control, the RAW default completes rather than stranding.
      onComplete(mech, moralityKept
        ? fcBuildMoralityLayer(gameData, moralStrength, moralWeak) : null);
      return;
    }
    onComplete(mech, null);
  }, [mechType, baseValue, mechDescriptor, selectedTradeIds, mechConfig, onComplete, hasForce,
      moralityKept, gameData, moralStrength, moralWeak]);

  // The layered Morality: locked at 50, no credit/XP trade through it (cap guard by construction —
  // this track contributes 0 to the +2,500cr/+10XP creation cap).
  //
  // R-MEP-1: the emotional pair is now named HERE, on the board's two-track screen, instead of
  // being deferred to the sheet. `descriptor` carries the strength; `descriptorWeak` is written
  // ONLY when the player departed from the book's pairing, and is ABSENT otherwise — absence is
  // what means "the pairing", so old saves and undeparted new ones read identically. Built through
  // the shared write rule so the absence is not re-implemented at the one site that can get it
  // wrong.
  var moralityLayer = fcBuildMoralityLayer(gameData, moralStrength, moralWeak);

  // ── THE TRANSPLANT (cluster two, screen two) ───────────────────────────────────────────────
  // Everything above is the DATA SOURCE and is untouched by this branch: the same filtered types,
  // the same `baseValue` off the same party-size rule, the same `handleConfirm`, the same saved-
  // pick re-admission. Below, the board's frame is handed those values. Nothing is recomputed.
  var LINE_COPY = {
    obligation: { name: FC_MECH_STEP_NAME.obligation, cite: 'Edge of the Empire p.38' },
    duty:       { name: FC_MECH_STEP_NAME.duty,       cite: 'Age of Rebellion p.44' },
    // THE BOARD DREW NO MORALITY FRAME (its section draws Obligation and Duty). This copy is
    // OURS, written to the same pattern in mechanics voice, and it is not a parity claim —
    // neither swept fixture reaches it. Morality is not a shared pool and must not borrow the
    // pooled sentence: it is personal, fixed at 50, and its trade is a one-off choice.
    // PRINTED p.48, NOT CORPUS p.52 (R-MCT-1). `swrpg_index/pdf_pages` reports fad CALIBRATED at
    // offset +4 — corpus = printed + 4 — so the 52 this line carried is the PDF page for printed
    // 48, which is what the board's own Morality lead cites. A player reading "p.52" and turning
    // to page 52 of Force and Destiny lands four pages past the rule. (The pair panel's cite
    // moved to p.48 with it at the 841b5aa7 refresh — R-MCT-2's authority, `mechanic-close-out`
    // A7; the pair rule and the Morality rule share the printed page.)
    // THE REGISTER'S THREE COPY LINES TRAVEL TOGETHER (R-MCO-A5-2: the unit is the DRAWING at
    // the address, not one string). The board's consular/healer Morality frame heads the list
    // "Emotional Strength", cites "39 strengths" and searches "Search Emotional Strength…"
    // (lab STABLE 841b5aa7, verbatim — A5-1 withdrew a pluralised re-derivation of this line).
    // Obligation and Duty have NO board frame of their own register, so their computed copy
    // stands ("Your Duty" · "N types" · "Search Duty…") until the board draws them.
    morality:   { name: FC_MECH_STEP_NAME.morality,   cite: 'Force and Destiny p.48',
                  list: { title: 'Emotional Strength', noun: 'strength', search: 'Search Emotional Strength…' } },
  };
  var copy = LINE_COPY[mechType] || LINE_COPY.obligation;
  // ONE COPY TABLE, one branch on the mechanic (the mechanism A5-2 leaves to the seat).
  var listCopy = copy.list
    ? { title: copy.list.title, cite: function(n) { return n + ' ' + copy.list.noun + (n === 1 ? '' : 's'); }, search: copy.list.search }
    : { title: 'Your ' + copy.name, cite: function(n) { return n + (n === 1 ? ' type' : ' types'); }, search: 'Search ' + copy.name + '…' };
  var pooled = mechType === 'obligation' || mechType === 'duty';
  // MODE C (fad p.338, the same disjunction `_hasForceAccess` already computes): a Force-sensitive
  // character in an Obligation/Duty campaign carries Morality TOO. It is the state the board's
  // two-track frames draw, and the reason this screen exists — the shipped flow asked about the
  // second track only after the first was finished.
  var twoTrack = hasForce && pooled;
  var lead = twoTrack
    ? ('You carry <b>two</b> tracks. The group’s ' + copy.name + ' is shared and you set your '
       + 'share of it; your own <b>Morality</b> rides alongside because your character is '
       + 'Force-sensitive. Both are named below before either is set.')
    : pooled
    ? ('Your table runs one shared ' + copy.name + ' pool and this is <b>your share</b> of it. '
       + 'You may take on more of it at creation in exchange for experience or credits.')
    : ('Your ' + copy.name + ' is your own — it starts at 50 and moves with what you do. '
       + 'You may make one trade at creation, and only one.');

  // THE TRACK'S LIVE VALUE, not its base: a trade taken must show in the ledger it moves.
  // `computeMechanic` is the one engine for that arithmetic and is asked here rather than
  // re-derived — a second path to this number is the defect the shared-core law names.
  var _live = computeMechanic(mechType, baseValue, mechDescriptor, selectedTradeIds, mechConfig);
  var liveValue = _live && typeof _live.finalValue === 'number' ? _live.finalValue : baseValue;
  // B-1379 / B-1492: the header's experience follows the trade on THIS step — the one pool (`creationXpPool`) asked with
  // the live mechanic; Remaining moves by the same difference, since nothing spent changes when a trade is taken.
  var livePool = (xpPoolWithMechanic && _live) ? xpPoolWithMechanic(_live) : xpPool;
  var liveRemaining = (Number(xpRemaining) || 0) + (livePool - (Number(xpPool) || 0));

  var tracks = [{
    name: copy.name,
    scopeWord: pooled ? 'group' : 'personal',
    scope: pooled ? 'Group · shared with your party' : 'Personal · yours alone',
    value: liveValue,
    line: pooled ? 'The party’s shared track: this is your share'
                 : 'Your own track: nobody else contributes to it',
    prose: pooled
      ? ('Everyone at the table contributes to one pool and the GM rolls against the total at '
         + 'each session’s start. Set by party size.')
      : ('It starts at 50 and moves as you act. Nothing at creation sets it but the one trade '
         + 'below.'),
    foot: 'You may trade on this track',
  }];

  // THE SECOND TRACK. Fixed at 50 and carrying NO trade — the creation cap is a property of the
  // pooled track only (fad p.341-342), which is why `computeMechanic` is not asked for a value
  // here: there is no arithmetic to do, and inventing a second path to a constant would be the
  // shared-core defect by name. The board's own frame prints exactly these words.
  if (twoTrack) {
    tracks.push({
      name: 'Morality',
      scopeWord: 'personal',
      scope: 'Personal · yours alone',
      value: 50,
      line: 'Yours alone: Conflict and Morality are personal',
      prose: 'Your character is <b>Force-sensitive</b>, so Morality runs alongside the group '
           + 'track, starting at <b>50</b>. It brings no extra XP or credits. You name an '
           + 'emotional pair and Conflict moves the number in play.',
      foot: 'No trade through this track',
      // THE KEEP/DECLINE, CARRIED ON THE CARD THAT NAMES THE TRACK (R-PMeC-2). Read by the PHONE
      // sheet only: the approved wide frame draws no control, and R-MIL-2 forbids a seat adding
      // one to it — so at mid/wide the default answers and the frame is untouched.
      kept: moralityKept,
      onKeep: setMoralityKept,
    });
  }

  var _S = (typeof window !== 'undefined') && window.SWRPGSources;
  var _idx = _S && _S.current() ? _S.current().index : null;
  var _q = (mechQuery || '').trim().toLowerCase();
  var rows = types
    .filter(function(t) { return !_q || String(t.name || '').toLowerCase().indexOf(_q) >= 0; })
    .map(function(t) {
      var src = t.source && _idx && _S.sourceLabel ? _S.sourceLabel(_idx, t.source) : t.source;
      return {
        id: t.key, name: t.name, description: t.description || '',
        // A2-1 (D-C2-4): "each attributed row carrying its source". The board's own sample rows
        // print none — so this span is a RULED DELTA and says so on the element, which is the
        // declared mechanism R-TTP-1 enumerates rather than an undeclared addition. The rows
        // with no book stay unmarked and always-offered, per shipped law.
        source: src || undefined,
        sourceRuledDelta: src ? 'mechanic-row-source-a2-1' : undefined,
        // MORALITY ONLY — obligation and duty types have no shadow, so this is undefined
        // there and every branch below it stays off. Derived at render from the register's
        // own pairing; nothing new is persisted.
        pairedWeakness: t.pairedWeaknessName
          ? { name: t.pairedWeaknessName, description: t.pairedWeaknessDesc || '' }
          : undefined,
        why: t._fromRetired ? 'your pick · from a book you switched off' : undefined,
      };
    });
  var selectedRow = rows.filter(function(r) { return r.id === mechDescriptor; })[0] || null;

  var partySizes = null;
  var _rule = mechData && mechData.startingValueRule;
  if (_rule && _rule.basis === 'partySize' && _rule.valuesByPartySize) {
    partySizes = _rule.valuesByPartySize.map(function(v) {
      var n = v.partySize === '6+' ? 6 : Number(v.partySize);
      return {
        n: n, label: String(v.partySize), value: v.startingValuePerPC,
        on: v.partySize === '6+' ? partySize >= 6 : String(v.partySize) === String(partySize),
      };
    });
  }

  function _money(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
  var tradeRows = trades.map(function(c) {
    var taken = selectedTradeIds.indexOf(c.id) >= 0;
    // WOULD THIS ONE BE LEGAL? Asked of the ENGINE, with the candidate added, so the cap that
    // disables a row is the same cap that would refuse it at confirm. A row disabled by a rule
    // written twice is a row that disagrees with itself.
    var probe = taken ? selectedTradeIds : selectedTradeIds.concat([c.id]);
    var name = c.label ? c.label : [
      c.xpDelta ? '+' + c.xpDelta + ' XP' : null,
      c.creditsDelta ? '+' + _money(c.creditsDelta) + ' credits' : null,
    ].filter(Boolean).join(' and ');
    return {
      id: c.id, name: name, trackLabel: copy.name,
      from: baseValue, to: baseValue + (c.valueDelta || 0),
      taken: taken,
      disabled: !computeMechanic(mechType, baseValue, mechDescriptor, probe, mechConfig),
    };
  });

  // ── THE PAIR PANEL (R-MEP-1/2) ────────────────────────────────────────────────────────────
  // Two-track only. Both registers take the SHELF'S SET through `fcFilterActive`, the same
  // D-C2-4 rule the main register takes — a strength from a book you switched off must not be
  // offered here either. The WEAKNESS list is the override menu, so it is filtered too; the
  // DERIVED partner is never filtered, because it is not offered, it is resolved (the same
  // reasoning the single-track morality branch above records).
  var pairPanel = null;
  if (twoTrack && gameData.narrativeMechanics.morPairs) {
    var _mp = gameData.narrativeMechanics.morPairs;
    var _strAll = fcFilterActive(_mp.strengths || [], null, false);
    var _weakAll = fcFilterActive(_mp.weaknesses || [], null, false);
    var _strObj = (_mp.strengths || []).filter(function(s) { return s.key === moralStrength; })[0] || null;
    // ONE resolver, even here: the panel shows what the SAVE would resolve to, so the screen and
    // the sheet can never disagree about which weakness this character has.
    var _resolved = _strObj
      ? CharResolve.moralityPair(
          { moralityLayer: { type: 'morality', descriptor: moralStrength,
                             descriptorWeak: moralWeak || undefined } }, _mp)
      : null;
    function _rows(list, q) {
      var _q = (q || '').trim().toLowerCase();
      return list
        .filter(function(t) { return !_q || String(t.name || '').toLowerCase().indexOf(_q) >= 0; })
        .map(function(t) { return { id: t.key, name: t.name }; });
    }
    var _weakSelKey = _resolved ? _resolved.weaknessKey : null;
    var _weakObj = (_mp.weaknesses || []).filter(function(w) { return w.key === _weakSelKey; })[0] || null;
    pairPanel = {
      // PRINTED p.48 (R-MCT-2; `mechanic-close-out` A7 — the board's pair_block cites it so at
      // lab STABLE 841b5aa7). THE SENTENCE IS THE BOARD'S, CHARACTER-EXACT (A7-1): the lab took
      // the ruled wording of `mechanic-emotional-pair-contract` Q1 unparaphrased so the app can
      // match it by string, and the pair-contract's rule — persist the DEPARTURE, never the
      // pairing — is what "the table's call" states.
      cite: 'Force and Destiny p.48',
      lead: "Strength and Weakness are paired on the book's d100 table.",
      strength: {
        title: 'Strength', count: _strAll.length, rows: _rows(_strAll, strQuery),
        selected: _strObj ? { id: _strObj.key } : null,
        query: strQuery, placeholder: 'Search strengths…', onSearch: setStrQuery,
        // CHANGING THE STRENGTH RE-LIGHTS ITS PARTNER — the override is dropped, because it was
        // an override OF a pairing that no longer applies. Keeping it would silently attach the
        // old weakness to a new strength, which is B-117's failure mode wearing a new hat.
        onPick: function(k) { setMoralStrength(k); setMoralWeak(null); },
        detail: _strObj ? { name: _strObj.name, description: _strObj.description || '' } : null,
      },
      weakness: {
        title: 'Weakness', count: _weakAll.length, rows: _rows(_weakAll, weakQuery),
        selected: _weakObj ? { id: _weakObj.key } : null,
        query: weakQuery, placeholder: 'Search weaknesses…', onSearch: setWeakQuery,
        // THE ABSENCE RULE, AT THE ONE PLACE A PLAYER CAN TRIGGER IT: picking the book's own
        // partner back sets null, not the key — so the save carries an override or nothing, and
        // `descriptorWeak` never appears holding the value it would have derived anyway.
        onPick: function(k) {
          setMoralWeak(_strObj && k === _strObj.weakKey ? null : k);
        },
        detail: _weakObj ? {
          name: _weakObj.name, description: _weakObj.description || '',
          note: _resolved && _resolved.pairedKey && _strObj
            ? 'Paired with ' + _strObj.name + ' on the book’s own table' : null,
        } : null,
      },
    };
  }

  var _next = (steps || [])[stepIndex + 1];
  return (
    <FCMechanicSheet
      band={band} stepName={copy.name}
      stepIndex={stepIndex} stepReached={stepReached} stepTotal={stepTotal}
      steps={steps} stepLabels={stepLabels} onJump={onJump} onBack={onBack}
      xpPool={livePool} xpSpentHere={0} xpRemaining={liveRemaining}
      soFar={soFar}
      lead={lead} cite={copy.cite}
      /* THE SECOND TRACK'S BOOK, beside the line's own. Mode c is FaD's rule applied inside an
         Edge/AoR campaign, so the head cites both — the board draws the pair. */
      cite2={twoTrack ? 'Force and Destiny p.338' : undefined}
      /* R-MEP-4, scoped to THIS surface and to the PINNED board: its two Force-sensitive
         mechanic frames omit the Force Powers step. Both characters are Force-sensitive — the
         two-track one by its specialisation, the morality one by its line — so `hasForce` is
         exactly the set of mechanic frames whose pinned board undercounts. */
      /* R-MEP-4's WAVE EXCEPTION IS RETIRED (R-MCO-2), on the expiry it was written with. It
         existed because the board pinned at `97226bf1` drew ELEVEN wave steps on its two
         Force-sensitive mechanic frames while the honest counter gives twelve, and it said in as
         many words that it "RETIRES the moment the set refreshes". The set has refreshed several
         times since and is now at `56186654`, where those frames draw TWELVE — so the exception
         had inverted: instead of excusing a step the board lacked, it was DELETING OUR OWN
         twelfth step from a comparison the board was ready to make, leaving the app two objects
         short. That is B-392, and it is the declaration-expiry trap rather than a wave defect.
         Nothing replaces it: the app and the board now draw the same twelve. */
      pair={pairPanel}
      tracks={tracks}
      listTitle={listCopy.title}
      listCite={listCopy.cite(rows.length)}
      searchValue={mechQuery} searchPlaceholder={listCopy.search}
      onSearch={setMechQuery}
      rows={rows} selectedRow={selectedRow}
      onPick={function(key) { setMechDescriptor(key); }}
      partySizes={partySizes} onPartySize={setPartySize}
      trades={tradeRows} onTrade={handleToggleTrade}
      tradeCite={pooled ? 'on the group track only' : 'one only'}
      commitLabel={_next && stepLabels ? ('Continue to ' + stepLabels[_next]) : 'Continue'}
      onConfirm={handleConfirm} />
  );
}







/* ── FC Talent Tree — LIFTED to lib/shared/treeView.jsx (F-100 M5 C7, ruling f100-m5-contracts §3 C7) ──
   The 11-function block lives there now, whole; this file keeps its three pinned helpers (glyphs, cleanMarkup,
   gameLineTitle) and INJECTS them, so the player tree draws as before. Module-top aliases re-point the 14 mounts,
   the 12 builder calls and FCTreeRail's entry body without touching a call site. */
window.SWRPGTree.configure({ clean: cleanMarkup, glyphs: glyphs, cite: gameLineTitle });
var { DirectionalTree, DirectionalTreeSheet, DirectionalTreeEntryBody, talentTreeToModel, forcePowerToModel } = window.SWRPGTree;

/* ── FC Force Powers Step (F&D only) ─────────────────── */
// Veteran review fix: F&D Custom was shipping no way to buy Force powers during creation.
// CRB p.282-299 lists the trees; each has a Basic Power that costs 10 XP with FR 1+ prereq.
// First cut: buy/unbuy basic power per tree. Upgrades deferred to in-play purchases.

// ── B-32: the ONE basic-Force-power buy core (ruling advancement-basic-force-power-triage §3) ──
// Shared by the CREATOR (FCForcePowersStep) and the sheet's ADVANCEMENT force section, so a
// Force-sensitive character can buy new basic powers in BOTH places off ONE RAW-cited implementation
// (never a second cost/list path — the anti-divergence pin guards this).
//
// basicForcePowerCost — printed basic cost = the canonical tree's row-0 anchor (5-20 XP, fad p.285).
// R-3B2: a canonical power missing its row-0 cost is a REGISTRY BUG — loud at render (trips every
// smoke's 0-console-errors assert; the card shows COST ? with BUY disabled), never a silent price.
// F-100 M12 B-1246: the read itself is CharResolve.forcePowerBasicCost, the ONE basic price (re-entry asks it too); this
// wrapper owns only the loud refusal.
function basicForcePowerCost(p, priceCtx) {
  var cost = CharResolve.forcePowerBasicCost(p, priceCtx);
  if (cost == null) {
    console.error('[canonical] force power ' + ((p && (p.id || p.name)) || '?') + ' missing row-0 basic cost — registry bug');
    return null;
  }
  return cost;
}
// B-88 — THE SIZE OF THE THING YOU ARE CHOOSING (lap C12; drawn in
// `Docs/mockups/creator-forcepowers.html`, scoped by `creator-program-completion-plan` LAP 2).
//
// The step priced the ENTRY and never the power. A basic power costs 5-20 XP; the same power fully
// bought costs 90-215, median 145 — NINE to TWENTY-ONE TIMES the number on the button. The screen's
// entire statement on that was one word: upgrades come "in play". So a player chose between powers
// on a price that is not the price of any of them, and the 253 upgrade cells that make up the real
// cost were not merely unpriced — before C3 they were not drawn at all.
//
// NOT A PRICE PAID NOW. This line never enters the XP budget and nothing here becomes buyable: it
// is the SHAPE of the commitment, printed where the commitment is made. `readOnly` on the tree
// (B-89, lap C3) made the same argument in geometry; this makes it in arithmetic.
//
// DERIVED FROM THE SAME STRUCTURE `basicForcePowerCost` READS, one cell deeper. The registry census:
// 21 basics + 253 upgrades = 274 cells, 3,080 XP to own every power — against a modal starting pool
// of 100. Nothing is hardcoded here and nothing is read back off the page (the census-echo rule): a
// registry edit re-prices these lines, and the guard recomputes its expectations the same way.
function forcePowerSize(p) {
  var tree = (p && p.tree) || [];
  var cells = [];
  tree.forEach(function(row) { (row.cells || []).forEach(function(c) { cells.push(c); }); });
  if (!cells.length) return null;
  var total = cells.reduce(function(sum, c) { return sum + (c.cost || 0); }, 0);
  // Row 0 cell 0 is the BASIC power — the thing the button already prices. Everything else is an
  // upgrade, which is why the count is cells-minus-one rather than a second registry field.
  return { upgrades: cells.length - 1, total: total };
}
// F-100 M11 R-M11R-5 (B-1240; ruling f100-m11-frames-card ADDENDUM 1 @ 406b526d): a reSpecialized power that REPLACES a
// book power carries `sources: []` (the pack's convention, R-M11B-10), and `isActiveWith` reads an empty list as
// unsourced app content — so with a pack on, the books switches could not hide it and the core-first sort lost it. The
// list asks the BOOK record of the same id instead (the device's pristine base view): filtered, core-sorted and
// name-sorted by it. A record with sources of its own, or an ADDED power (no book record), is read as itself:
// unsourced, always shown, sorted among the non-core. The record itself is never changed.
function fcPowerBookOf(rec) {
  if (!rec || (rec.sources && rec.sources.length)) return rec;
  var base = (typeof window !== 'undefined') && window._canonicalCharbuildBase;
  var book = base && base.forcePowers && base.forcePowers[rec.id];
  return book || rec;
}
// buildBasicForcePowerList — active-sources filter + opt-in line gate (BOOKS-1c) + core-first sort
// (F&D CRB powers ahead of supplements, then alphabetical) — each read off fcPowerBookOf (R-M11R-5).
function buildBasicForcePowerList(allPowers, gameLine) {
  var _linePref = !!(window.SWRPGSources && window.SWRPGSources.lineFilterOn && window.SWRPGSources.lineFilterOn());
  var _kept = {};
  fcFilterActive((allPowers || []).map(fcPowerBookOf), gameLine ? [gameLine] : [], _linePref)
    .forEach(function(b) { if (b) _kept[b.id] = true; });
  var filtered = (allPowers || []).filter(function(rec) { return rec && _kept[rec.id]; });
  // B-336 LOGIC SITE. This listed the three core TITLES and matched against them. "Is this a core
  // book" is `group === 'Core'` on the vocabulary row — no list to keep in step, and no silent
  // failure when the registry starts storing keys (a key matches none of the three titles, so core
  // powers would simply have stopped sorting first, invisibly).
  var _S = window.SWRPGSources, _cur = _S && _S.current(), _idx = _cur && _cur.index;
  var isCore = function(rec) { return !!(_idx && _S.hasCoreSource(_idx, fcPowerBookOf(rec))); };
  return filtered.slice().sort(function(a, b) {
    var aCore = isCore(a);
    var bCore = isCore(b);
    if (aCore !== bCore) return aCore ? -1 : 1;
    return (fcPowerBookOf(a).name || '').localeCompare(fcPowerBookOf(b).name || '');
  });
}
// ForcePowerBuyList — the shared basic-power card list. isOwned(p)→bool, onBuy(p, cost), onRefund(id)
// optional (creator only). hideOwned filters out owned powers (advancement, where owned live in the
// upgrade list already). tourId anchors the first card (creator tutorial).
// B-41: `forceRating` is the character's RESOLVED rating (resolvedForceRating), and a power whose
// printed prerequisite it does not meet is shown-and-priced but NOT buyable — the requirement badge
// is the reason, so the blocked control is never unexplained.
// `priceCtx` (F-100 M12, DARK): the sheet's CharResolve.careerPowerPriceCtx — the Mentor discount on a career power, after
// creation (FaD Core p.109). The creator passes none, so it prices row 0 (the discount never applies at creation).
function ForcePowerBuyList({ powers, isOwned, xpRemaining, accent, gameLine, onBuy, onRefund, hideOwned, tourId, onInspect, forceRating, paper, held, priceCtx }) {
  var list = buildBasicForcePowerList(powers, gameLine);
  if (hideOwned) list = list.filter(function(p) { return !isOwned(p); });
  if (list.length === 0) return null;
  return (
    <div className="hp-bands" style={{ display: 'flex', flexDirection: 'column', gap: onInspect ? '6px' : '8px' }}>
      {list.map(function(p, idx) {
        var owned = isOwned(p);
        var basicCost = basicForcePowerCost(p, priceCtx);
        var canAfford = owned || (basicCost != null && xpRemaining >= basicCost);
        // B-41: two independent reasons a buy can be refused — price and prerequisite. They are kept
        // separate so the surface can say WHICH one applies; `canBuy` is what the control obeys.
        var frMet = owned || meetsForceRating(p, forceRating);
        var canBuy = canAfford && frMet && !held;   // B-855: a HELD sheet learns nothing (the sheet passes `held`; the creator never does)
        // Full description; strip the redundant "Force Power: <Name>" header the CRB prose ships with.
        // R3 Q2b — THE EATER, not a catch-all. This read `.replace(/\[[^\]]+\]/g, '')`: the SAME
        // glyph-eater as `\[.*?\]` wearing a different spelling, which is exactly why the census
        // regex for the catch-all could not see it. It deletes every dice symbol out of a Force
        // power's prose on the card the player buys it from. `desc` stays a STRING here on purpose:
        // the "Force Power: <Name>" header surgery below is a regex over it, and it is handed to
        // `onInspect` as `sel.desc`, where the DETAILS pane runs the drawer. Both render sites in
        // this component draw it through `glyphs`.
        var desc = cleanMarkup(p.description || '').replace(/\s+/g, ' ').trim();
        var nameEsc = (p.name || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        desc = desc.replace(new RegExp('^Force\\s+Power\\s*:\\s*' + nameEsc + '\\s*', 'i'), '');
        desc = desc.replace(/^Force\s+Power\s*:\s*/i, '').trim();
        // B-336 LOGIC SITE. This preferred the F&D core entry by matching its full TITLE, and fell
        // back to sources[0] on a miss — so under key storage it would have silently stopped
        // preferring F&D rather than reporting anything. Ask the vocabulary for the row's id.
        var _allSrc = p.sources || [];
        var _S2 = window.SWRPGSources, _cur2 = _S2 && _S2.current(), _idx2 = _cur2 && _cur2.index;
        var _fadIdx = _idx2 ? _allSrc.findIndex(function(s) {
          var m = _S2.sourceMeta(_idx2, s);
          return !!(m && m.id === 'fad');
        }) : _allSrc.indexOf('Force and Destiny Core Rulebook');
        // B-336 force-powers wave (ADDENDUM 62): the chosen source prints its TITLE — a key never reaches the row or the pane.
        var _srcPick = _fadIdx >= 0 ? _allSrc[_fadIdx] : (_allSrc[0] || '');
        var srcLabel = _srcPick ? gameLineBookLabel(_srcPick) : '';
        var _s1 = window.SWRPGSources && window.SWRPGSources.removedLine ? window.SWRPGSources.removedLine(p) : null;   // S1: the book line, pages and all
        if (_s1 != null) srcLabel = _s1;
        // onInspect (ADVANCEMENT, Jason 2026-07-21): a COMPACT row — name + a lit owned / cost indicator, no
        // inline description or BUY; tapping teaches + buys in the DETAILS pane (like the owned powers).
        // B-625 (the paper order): the buy list on the paper sheet — each power an entry: the name, the cost in the
        // head (or the refusal: not enough XP · requires Force rating N), the size line, the description folded
        // behind a teaser, the source; LEARN as the kit's commit. Same list, same spine (onBuy / onRefund).
        if (paper) {
          var size = forcePowerSize(p); var need = minForceRatingOf(p); var have = Number(forceRating) || 0;
          var refusal = owned ? null : held ? 'Held' : !frMet ? ('Requires Force rating ' + need + ' — you have ' + have) : !canAfford ? ('Not enough XP — ' + basicCost + ' needed, ' + xpRemaining + ' left') : null;
          var teaser = (window.SWItems && window.SWItems.teaserBeforeToken) ? window.SWItems.teaserBeforeToken(desc, 110) : '';   // B-1723: the one teaser (ADDENDUM 566); guarded: lib/items.js has no stamp, so the edge can serve it older (ADDENDUM 569)
          // F-100 surfacing K8 (R-SCC-5, ADDENDUM 2 F4): the MENTOR DISCOUNT says itself — the price the row charges is
          // forcePowerBasicCost's with the sheet's priceCtx; the gap to the printed row-0 price (no ctx) is the discount,
          // so the button reads "Learn · N XP (Mentor −5)" and the row carries the because. Dark exactly as the price is.
          var printedCost = priceCtx ? CharResolve.forcePowerBasicCost(p) : basicCost;
          var mentorOff = (!owned && basicCost != null && printedCost != null && printedCost > basicCost) ? printedCost - basicCost : 0;
          return (
            <div className="sb-e sb-fp" key={p.id} data-testid={'growth-buy-row'} data-power={p.id} data-refused={refusal ? '1' : '0'} data-owned={owned ? '1' : '0'}>
              <div className="sb-e-h"><span className="sb-e-n">{p.name}</span>
                {owned ? <span className="sb-e-m">Owned</span> : refusal ? <span className="sb-refuse" data-testid="growth-buy-refusal">{refusal}</span> : <span className="sb-e-m">{basicCost == null ? 'Cost ?' : basicCost + ' XP'}</span>}
                {owned ? (onRefund ? <button type="button" className="hp-quiet" onClick={function() { onRefund(p.id); }}>Refund</button> : null)
                  : <button type="button" className={canBuy ? 'hp-commit' : 'hp-quiet'} data-testid="growth-buy" data-held={held ? '1' : undefined} disabled={!canBuy}
                      data-mentor={mentorOff ? mentorOff : undefined}
                      aria-label={'Learn ' + p.name + (basicCost != null ? ' for ' + basicCost + ' XP' : '') + (mentorOff ? ', Mentor discount' : '')}
                      onClick={function() { if (canBuy && basicCost != null) onBuy(p, basicCost); }}>{'Learn' + (basicCost != null ? ' · ' + basicCost + ' XP' : '') + (mentorOff ? ' (Mentor \u2212' + mentorOff + ')' : '')}</button>}
              </div>
              {mentorOff ? <p className="sb-e-t" data-mentor-why={p.id} style={{ margin: '4px 0 0', fontWeight: 600 }}>{'A career power \u2014 Mentor discount (FaD p.109)'}</p> : null}
              {size ? <div className="sb-e-l" data-force-size={p.id}><div>Upgrades <b>{size.upgrades}</b></div><div>Whole power <b>{size.total + ' XP'}</b></div></div> : null}
              {desc ? <details className="sb-fold"><summary className="sb-e-h"><span className="sb-e-n">What it does</span>{teaser ? <span className="sb-e-m sb-fold-teaser">{teaser}</span> : null}<i className="sb-grp-glyph" aria-hidden="true">▾</i></summary><p className="sb-e-t">{glyphs(desc)}</p></details> : null}
              {srcLabel ? <p className="sb-e-t" style={{ margin: '4px 0 0' }}><span className="sb-e-m">{srcLabel}</span></p> : null}
            </div>);
        }
        if (onInspect) {
          return h('div', { key: p.id, 'data-tour-id': idx === 0 ? tourId : undefined,
            onClick: function() { onInspect({ power: p, cost: basicCost, owned: owned, canAfford: canAfford, desc: desc, srcLabel: srcLabel,
              frMet: frMet, frNeed: minForceRatingOf(p), frHave: Number(forceRating) || 0,
              doBuy: function() { if (!owned && canBuy && basicCost != null) onBuy(p, basicCost); },
              doRefund: function() { if (owned && onRefund) onRefund(p.id); } }); },
            style: { padding: '9px 12px', cursor: 'pointer', borderRadius: 6,
              background: owned ? accent + '12' : 'rgba(255,255,255,0.03)',
              border: '1px solid ' + (owned ? accent + '55' : 'rgba(255,255,255,0.08)'),
              borderLeft: '3px solid ' + (owned ? accent : 'rgba(255,255,255,0.15)'),
              display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 } },
            h('div', { style: { minWidth: 0 } },
              h('div', { style: { fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 'var(--fs-sm)', color: '#fff', minWidth: 0, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' } }, p.name),
              minForceRatingOf(p) ? h('div', { style: { marginTop: 2 } }, h(ForceRatingReq, { rec: p, forceRating: forceRating, compact: true })) : null),
            h('span', { style: { flexShrink: 0, fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-2xs)', letterSpacing: '0.12em', color: owned ? accent : 'rgba(255,255,255,0.55)', textShadow: owned ? '0 0 8px ' + accent + '66' : 'none' } }, owned ? '✦ OWNED' : (basicCost != null ? basicCost + ' XP' : 'COST ?')));
        }
        return (
          <div key={p.id} data-tour-id={idx === 0 ? tourId : undefined} style={{
            padding: '10px 12px',
            background: owned ? accent + '12' : 'rgba(255,255,255,0.03)',
            border: '1px solid ' + (owned ? accent + '55' : 'rgba(255,255,255,0.06)'),
            borderLeft: '3px solid ' + (owned ? accent : 'rgba(255,255,255,0.12)'),
            borderRadius: '6px',
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', marginBottom: '4px' }}>
              <div style={{ fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 'var(--fs-lg)', color: '#fff' }}>
                {p.name}
                {owned && <span style={{ fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-2xs)', letterSpacing: '0.16em', color: accent, marginLeft: '6px' }}>OWNED</span>}
              </div>
              <button type="button" onClick={function() { if (owned) { if (onRefund) onRefund(p.id); } else if (canBuy) { onBuy(p, basicCost); } }}
                disabled={!owned && !canBuy}
                style={{
                  // AS-6 44px TAP FLOOR (lap C1). Was `padding: '4px 10px'` → 22px tall; the Phase A
                  // recon measured 21 of this step's controls under the floor at every width.
                  // min-height + centring rather than a bigger font: the label keeps its size.
                  minHeight: '44px', padding: '4px 14px',
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                  background: owned ? 'rgba(255,80,80,0.15)' : (canBuy ? accent + '30' : 'rgba(255,255,255,0.04)'),
                  border: '1px solid ' + (owned ? 'rgba(255,120,120,0.5)' : (canBuy ? accent + '70' : 'rgba(255,255,255,0.1)')),
                  borderRadius: '4px',
                  fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 'var(--fs-2xs)', letterSpacing: '0.12em',
                  color: owned ? '#FFC4C4' : (canBuy ? accent : 'rgba(255,255,255,0.25)'),
                  cursor: (!owned && !canBuy) ? 'not-allowed' : 'pointer',
                }}>
                {owned ? (onRefund ? 'REFUND' : 'OWNED') : basicCost == null ? 'COST ?' : (canBuy ? 'BUY ' + basicCost + ' XP' : basicCost + ' XP')}
              </button>
            </div>
            {/* B-88 — the size line, above the description exactly as drawn. It sits under the
                price it corrects, so the two numbers are read together rather than a screen apart. */}
            {(function() {
              var size = forcePowerSize(p);
              if (!size) return null;
              return (
                <div data-force-size={p.id} style={{ fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-2xs)', letterSpacing: '0.06em', color: 'rgba(255,255,255,0.5)', marginBottom: '5px' }}>
                  {size.upgrades} upgrades · <b style={{ color: 'rgba(255,255,255,0.75)', fontWeight: 700 }}>{size.total} XP</b> for the whole power
                </div>
              );
            })()}
            {/* R3 Q2b — the drawer. `desc` now carries its glyph tokens (the eater above is
                structural-only), so the card DRAWS the dice symbols instead of eating them. */}
            <div style={{ fontFamily: 'var(--font-body)', fontSize: 'var(--fs-sm)', lineHeight: 1.55, color: 'rgba(255,255,255,0.75)' }}>{glyphs(desc)}</div>
            <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'baseline', gap: '4px 12px', marginTop: '4px' }}>
              <span style={{ fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-xs)', letterSpacing: '0.14em', color: 'rgba(255,255,255,0.65)' }}>{srcLabel || ''}</span>
              <ForceRatingReq rec={p} forceRating={forceRating} />
            </div>
          </div>
        );
      })}
    </div>
  );
}



/* ── C15 — THE MOTIVATION STEP (RAW Step 8) ───────────────────────────────────────────────────
   Replaces four free-text boxes (DESIRE / FEAR / STRENGTH / FLAW) — Jason's complaint 8 — with the
   book's own structure: ONE Motivation, a general CATEGORY then a SPECIFIC within it.

   AUTHORITIES, cited not re-decided: `motivation-hooks-raw-mapping` + Amendments 1-2 (ONE
   motivation, singular throughout — EotE Step Eight's Rodian walkthrough) · `b103-motivation-save-
   shape` (the save contract) · `c15-motivation-roll-has-no-ranges` (what ROLL can and cannot do
   today) · table numbers from checkpoint 25b0028: Table 2-5 category d10 p.103; Tables 2-6/2-7/2-8
   specifics p.104-105. The page budget is SPENT — nothing here re-reads a page.

   ROLL IS ASYMMETRIC BY DATA, NOT BY DESIGN, and the ruling fixed the shape:
     · CATEGORY tier — ROLL is LIVE. Table 2-5's d10 ranges (1-3 Ambition · 4-6 Cause · 7-9
       Relationship · 10 REROLL) are recorded in the ruling itself, so nothing is invented.
     · SPECIFIC tier — CHOOSE-only, with one stated line. The book's specific tables are RANGE
       WEIGHTED and those ranges were never ingested: all 283 specifics carry name + category and
       no roll data at all. A d100 button would have to invent the ranges, which is the one thing
       the plan forbade. Deferred to the ranges data lap, with the absence STATED so it reads as a
       decision rather than an oversight.
     · A uniform random pick dressed as the table was REJECTED BY NAME — the book's distribution is
       weighted, so uniform-that-looks-like-the-table moves the invention from the numbers to the
       distribution.

   A ROLLED and a CHOSEN motivation are INDISTINGUISHABLE in the save, which is correct: the save
   records WHAT the character wants, not HOW the player arrived at it. */



/* ── FC Gear Step (B-94, lap C4) ──────────────────────
   The step itself, once the catalogue moved into the shared store. It holds what the wizard should
   hold — the purse, what has been bought, and the door — and nothing the store already does well.
   The creator's own 283-item parallel gear browser is deleted; this is what replaced it. */
// ═══ B-563 · STEP 10 · GEAR — the revision's gear sheet, transplanted at all three bands (dark) ═══
// Lifted verbatim from revision/creator-2026-09-10 (fcGearLineStats … FCGearSheet). The legacy
// FCGearStep below stays for the visitor's page; the store overlay is shared by both.
function fcGearLineStats(row, reg) {
  var sec = row.section || 'gear';
  var rec = reg && reg[sec] && reg[sec][row.key];
  if (!rec) return '–';
  if (sec === 'weapons') {
    var d = rec.damage || {};
    var base = d.base && d.base !== 'flat' ? d.base.charAt(0).toUpperCase() + d.base.slice(1) : '';
    var v = Number(d.value) || 0;
    var dmg = base ? base + ' ' + (v >= 0 ? '+' : '') + v : String(v);
    return 'Dmg ' + dmg + ' · Crit ' + critText(rec.crit);
  }
  if (sec === 'armor') {
    var s = 'Soak +' + (Number(rec.soak) || 0);
    if (Number(rec.defense) > 0) s += ' · Def +' + Number(rec.defense);
    return s;
  }
  return '–';
}

// THE ONE CALL (R-GC-3, PRAXIS §5): the draft's rows, mapped into the resolver's id-ref shape with
// their registry records, and the character's Brawn. The resolver's `over` is the state.
//
// THE ONE SUIT IS WORN — Jason 2026-09-19, "Worn" (B-700). Asked whether the creator's gear preview
// should count the single armour as worn or as carried, he answered "Worn", so the preview passes
// `state: 'worn'`. That is the SAME shape the assembly writes (`buildCanonicalEquipment`, B-699 —
// `{ id: id, state: 'worn' }`) and the same key `deriveItemState` reads first, so the gear step, the
// review preview and the saved sheet now print ONE number where they printed two. `computeEncumbrance`
// reads that key off THIS entry (`armor.state === 'worn'` → `Math.max(0, enc − 3)`, and a worn suit's
// own `encumbrance_threshold_bonus` then counts), which is why the state sits on the record object
// handed over rather than anywhere else: this function passes registry RECORDS, not id-refs, and the
// one resolver keys the reduction on the entry's `state`. The −3 is EotE p.168's — "Reduce the
// encumbrance value of all armor by 3 when worn".
//
// THE OLD CITE WAS MISATTRIBUTED, not merely superseded, and that is worth writing down so it is not
// restored. This comment read: UNWORN — carried "as just another item" (eote p.152's words), under
// R-GC-3. EotE p.152 describes the carried state GENERALLY — "the encumbrance value of armor … is
// different when it's worn, where the weight is distributed appropriately, and when it's carried" —
// and gives NO creation-time default either way; and R-GC-3 says nothing about the state at all,
// only that this is ONE call over the mapped rows. RAW was silent, so the citation never held.
//
// A SECOND ARMOUR ROW STILL RIDES AS GEAR. Armour is SINGULAR at creation (R-ASS-1's worn-singular),
// so a second armour row on an old draft is carried as gear rather than dropped — which is now the
// same rule as the store's R-SPC-9: the first suit worn, the rest in the pack.
// F-100 M9 (R-M9B-3): `speciesDelta` is the species' encumbrance_threshold_delta off the creator's RECORD
// (CharResolve.speciesEncumbranceDeltaOf), passed through to the one computation; 0 with the species rules key OFF.
function fcGearEncumbrance(inv, reg, brawn, speciesDelta) {
  var eq = { weapons: [], armor: null, gear: [] };
  (inv || []).forEach(function(it) {
    var sec = it.section || 'gear';
    var rec = reg && reg[sec] && reg[sec][it.key];
    var base = Object.assign({}, rec || { name: it.name, encumbrance: Number(it.enc) || 0 });
    var n = Math.max(1, Number(it.qty) || 1);
    if (sec === 'weapons') { for (var i = 0; i < n; i++) eq.weapons.push(Object.assign({}, base)); }
    else if (sec === 'armor' && !eq.armor) { eq.armor = Object.assign(base, { state: 'worn' }); }
    else { eq.gear.push(Object.assign(base, { qty: n })); }
  });
  var CR = window.CharResolve;
  if (!CR || typeof CR.computeEncumbrance !== 'function') return null;
  return CR.computeEncumbrance(eq, { brawn: Number(brawn) || 0 }, speciesDelta);
}

/* ── THE GEAR STEP'S THREE SHARED PARTS ────────────────────────────────────────────────────────
   Lifted out of `FCGearSheet` so the phone sheet below draws THE SAME OBJECTS rather than a copy of
   them — the rule `build-phone-gameline` set when it lifted `fcGameLinePlates` out of its own tree,
   and PRAXIS §5's "a second resolution path for the same number is a defect" one level down: a
   second COPY of the same markup is the same defect wearing a template's clothes. Both bands call
   these; neither owns them.

   THE DOOR AND THE PER-LINE REMOVE ARE CARRIED FORWARD, NOT INVENTED (ruling `phone-gear-census`
   R-PGeC-2 / its KEEP-UNDRAWN rows). The approved PHONE frame `phone_gear()` draws neither — its
   only non-nav control is the commit — while the approved DESKTOP frame `board_gear_1920` draws
   the door once and Remove five times. So the phone keeps the desktop frame's own idiom for both
   and the lab is asked for a phone frame that shows them; the build does not wait. That is why
   these are functions and not phone-local JSX: the thing being carried forward is the DESKTOP
   FRAME'S markup, and the only way to be sure of that is to make it the same markup. */
function fcGearDoor(onShop) {
  return (
    <React.Fragment>
      {/* THE CATALOGUE IS A DOOR, NOT A LIST (Jason 2026-08-27; R-GC-4): the shared store. Its
          interior is out of this card's OWNS — the same component, unchanged, at every band. */}
      {/* B-1545 (release-r7-bug-burndown ADDENDUM 77, ASK 2 (a)): the plate that stood here is GONE. The copy-voice
          sweep's CUT-3 (`32cf86508`, census row :9278:12, "narrates the store") cut the string node before `<b>rarity</b>`
          and left the rest as a mid-sentence fragment ("rarity shown as the difficulty…"); its sibling row (:9670:187)
          shows the cut meant the whole sentence. The ruled cut is finished, not the board's sentence restored. */}
      {/* `data-testid` KEPT: `smoke_creator_as9`'s door leg picks the door by it (R-PGeC-2). */}
      <button type="button" className="hp-commit hp-door" data-testid="creator-open-store" onClick={onShop}>Open the Store</button>
    </React.Fragment>
  );
}
function fcGearKitSechead(lines) {
  return (
    <div className="hp-sechead" style={{ margin: '22px 0 11px' }}>
      <h2>What You Are Carrying</h2>
      <span className="hp-cite" data-gear-lines={lines}>{lines + (lines === 1 ? ' line' : ' lines')}</span></div>
  );
}
/* THE STATS SPAN IS A BAND DIFFERENCE THE FRAME ITSELF DECLARES, and it is the one place this
   build does NOT carry the desktop row forward whole. The two approved frames draw the row
   DIFFERENTLY on purpose: `board_gear_1920` runs name · STATS · price · enc · Remove (five
   objects), `phone_gear()` runs name · price · enc (three). That is not the same silence the door
   and Remove sit in — the phone frame OMITS those two entirely, which is why R-PGeC-2 fills them
   from the desktop, but it POSITIVELY DRAWS this row and says it has three spans. A frame that
   draws a thing is the authority on that thing, so the stats line goes at 390 and the row obeys
   the drawing. `compact` is a parameter and not a second copy of the plate: the difference is
   DECLARED in one place rather than duplicated into a phone-local block that can drift.
   FLAGGED at the gate — R-PGeC's KEEP/RETIRE table enumerates the door and Remove and does not
   reach this third object, so the reading above is the seat's and the architect should see it. */
function fcGearKitPlate(inv, reg, onSell, compact) {
  return (
    <div className="hp-plate hp-bands" data-pad="data" data-gear-kit="1">
      {/* UNDRAWN — NOTHING CARRIED: the app's sentence, in idiom. */}
      {!inv.length ? <span className="hp-none" data-gear-empty="1">{'Nothing yet. A character can begin with no gear at all.'}</span> : null}
      {inv.map(function(it, i) {
        var n = Math.max(1, Number(it.qty) || 1);
        return (
          <div className="hp-buy hp-gearline" key={it.key + ':' + i} data-carried={it.key} data-gear-section={it.section || 'gear'}>
            <span className="hp-buy-name">{it.name + (n > 1 ? ' \u00d7' + n : '')}</span>
            {compact ? null : <span className="hp-buy-cost" data-gear-stats="1">{fcGearLineStats(it, reg)}</span>}
            <span className="hp-buy-step" data-gear-price={(Number(it.price) || 0) * n}>{((Number(it.price) || 0) * n) + ' cr'}</span>
            <span className="hp-buy-cost" data-gear-enc={(Number(it.enc) || 0) * n}>{((Number(it.enc) || 0) * n) + ' enc'}</span>
            <button type="button" className="hp-buy-btn" data-gear-remove={it.key} aria-label={'Remove ' + it.name}
              onClick={function() { onSell(it.key); }}>Remove</button>
          </div>
        );
      })}
    </div>
  );
}

/* ── THE BECAUSE LINES (F-100 surfacing, ruling `f100-surfacing-creator-concept` R-SCC-6 as errata'd, ADDENDUM 4 FLAG 1 (iii),
   ADDENDUM 18 Q4; approved frame K9) — one species row in the record's form: "+1,000 after creation — Deep Pockets (Muun)",
   "+1,100 — Vast Wealth (Anomid)", "−2 — No Hands (Fefze)" (D4: the typographic minus, the record's order). The rows are
   the purse reader's `rows` (the credits memo) and speciesEncumbranceRowsOf — the same walks the figures read. */
function fcBecauseLine(r) {
  var n = Number(r && r.amount) || 0;
  return (n < 0 ? '\u2212' : '+') + Math.abs(n).toLocaleString('en-US') + (r.timing === 'after_creation' ? ' after creation' : '')
    + ' \u2014 ' + r.ability + ' (' + r.species + ')';
}
function fcBecauseSpans(rows, attr) {
  return (rows || []).map(function(r, i) {
    var a = { key: attr + i, className: 'hp-why', style: { display: 'block', marginTop: '4px', color: 'var(--doc-ink)' } };
    a[attr] = '1';
    return React.createElement('span', a, fcBecauseLine(r));
  });
}

/* ── THE STARTING ENTITLEMENT (F-100 surfacing, ruling `f100-surfacing-creator-concept` R-SCC-3; D-229 Q1 (a) ii ships it
   LIVE, ADDENDUM 18; approved frame K7, `Docs/mockups/f100-surfacing-creator.html` @ 1e2438f9f) ──────────────────────
   ONE reader for the gear step, the review and the sheet GEAR card: the career record's `starting_entitlements`, each
   with `declined` read off the save's `entitlements` ([{id, declined: true}], written by the gear step's tick ONLY while
   ticked; absent = granted — brief §3.1). An id the career does not carry is ignored, so nothing invents a line. */
function fcEntitlementLines(careerRec, saved) {
  var off = {};
  (Array.isArray(saved) ? saved : []).forEach(function(e) { if (e && e.id && e.declined === true) off[e.id] = true; });
  return ((careerRec && careerRec.starting_entitlements) || []).filter(function(e) { return e && e.id; }).map(function(e) {
    return { id: e.id, name: e.name || e.id, note: e.note || '', declined: !!off[e.id] };
  });
}
// The tick's write: the next `entitlements` value for a press — the declined ids of THIS career, or undefined (the field
// goes; absent = granted).
function fcEntitlementToggle(lines, id) {
  var next = (lines || []).filter(function(l) { return l.id === id ? !l.declined : l.declined; })
    .map(function(l) { return { id: l.id, declined: true }; });
  return next.length ? next : undefined;
}
// The gear step's plate: "<name> — <note>" and the Decline tick in the option-row idiom (hp-head + hp-box, D6).
function FCEntitlementPlate({ lines, onToggle }) {
  if (!lines || !lines.length) return null;
  return (
    <div data-entitlements="1">
      <div className="hp-sechead" style={{ margin: '20px 0 10px' }}><h2>Starting Entitlement</h2></div>
      <div className="hp-plate" data-pad="data">
        {lines.map(function(l, i) {
          return (
            <React.Fragment key={l.id}>
              <p className="hp-prose hp-prose-sm" data-entitlement-line={l.id}
                style={{ margin: (i ? '12px' : '0') + ' 0 8px', maxWidth: 'none' }}>{l.name + (l.note ? ' \u2014 ' + l.note : '')}</p>
              <button type="button" className="hp-head" data-state={l.declined ? 'active' : 'passive'}
                aria-pressed={l.declined ? 'true' : 'false'} data-entitlement-decline={l.id}
                aria-label={'Decline the ' + l.name}
                onClick={function() { onToggle(l.id); }}>
                <span className="hp-box" data-on={l.declined ? '1' : '0'} />
                <span className="hp-name">Decline</span>
              </button>
            </React.Fragment>
          );
        })}
      </div>
    </div>
  );
}

/* ── THE GEAR PHONE SHEET (`phone-gear-census` R-PGeC-1) ───────────────────────────────────────
   ONE COLUMN IN THE FRAME'S ORDER, under the shared `FCPhoneShell`. `phone_gear()` at the freeze
   pin runs: runhead -> wave -> hr -> a two-cell status pill -> maker/desig -> the lead plate with
   its cites -> "What You Are Carrying" -> the kit rows -> a collapsed "So Far" -> the commit. The
   shell draws the first three and the last; this draws the rest, in that order.

   THE DOOR SITS WHERE THE DESKTOP PUTS IT — before the kit, because the desktop frame Jason
   approved draws it there and the phone frame draws it nowhere at all. Placing it after the kit
   would have been just as consistent with the phone frame's silence, which is exactly why the
   silence is not the authority here: the desktop frame is (R-PGeC-2).

   NO STEP-LEVEL SCROLL ZONE. The shell's own box scrolls since `phone-shell-scroll` merged, and a
   second scroller inside it is the trap that lap existed to remove — a pane that scrolls within a
   pane that scrolls strands the content of whichever one the thumb misses. The kit is a plain
   plate; it grows and the shell carries it. */
function FCGearSheetPhone(p) {
  var inv = p.inventory || [], credits = p.credits || { total: 500, spent: 0, remaining: 500 };
  var reg = p.reg || null;
  var enc = fcGearEncumbrance(inv, reg, p.brawn, p.speciesEncDelta);
  var overBudget = credits.remaining < 0;
  var overLimit = !!(enc && enc.over > 0);
  var nextStep = (p.steps || [])[(p.stepIndex || 0) + 1];
  var nextLabel = nextStep && p.stepLabels ? p.stepLabels[nextStep] : 'the next step';
  return (
    <FCPhoneShell band={p.band} rootAttrs={{ 'data-gear-step': '1' }}
      stepIndex={p.stepIndex} stepReached={p.stepReached} stepTotal={p.stepTotal}
      steps={p.steps} stepLabels={p.stepLabels}
      onBack={p.onBack} onJump={p.onJump}
      /* THE PILL IS THE RAIL, FOLDED. The desktop rail carries Starting / Spent / Left and Carried
         of limit; the frame's pill carries the two figures a player at the counter actually needs,
         and the rest is one tap away in the store. Same resolver, same numbers. */
      status={<React.Fragment>
        <div><span className="hp-status-k">Left</span>
          <span className="hp-status-v" data-creator-purse={credits.remaining}
            data-over={overBudget ? '1' : undefined}
            style={{ color: overBudget ? 'var(--doc-action)' : undefined }}>{credits.remaining + ' cr'}</span></div>
        <div><span className="hp-status-k">Carried</span>
          <span className="hp-status-v" data-gear-carried={enc ? enc.carried : ''} data-gear-limit={enc ? enc.limit : ''}
            data-over={overLimit ? '1' : undefined}
            style={{ color: overLimit ? 'var(--doc-action)' : undefined }}>
            {enc ? enc.carried + ' of ' + enc.limit : '\u2013'}</span>
          {fcBecauseSpans(p.speciesEncRows, 'data-creator-enc-why')}</div>
      </React.Fragment>}
      /* NEVER GATED, and now never TWO-WORDED either: the legacy phone step's
         "CONTINUE" / "CONTINUE WITHOUT GEAR" pair RETIRES with its mount (R-PGeC's table) for the
         frame's own "Continue to Review \u203a". The label is DERIVED from the walk rather than
         typed, so a character who skips a step still reads the truth. */
      act={<button type="button" className="hp-commit" data-creator-commit="1" onClick={p.onConfirm}>
        {'Continue to ' + nextLabel + ' '}<span>{'\u203a'}</span></button>}>

      <div style={{ display: 'flex', alignItems: 'center', gap: '11px', marginTop: '14px' }}>
        <span className="hp-slash"><i /><i /><i /></span>
        <div className="hp-maker">{fcMakerLine((p.stepIndex == null) ? null : p.stepIndex + 1, p.stepTotal)}</div>
      </div>
      <h1 className="hp-desig">{p.stepName}</h1>
      <div className="hp-desig-rule" />

      <div className="hp-plate" data-pad="read" style={{ marginTop: '11px' }}>
        <p className="hp-lead" data-step-standfirst="1" style={{ margin: 0 }}>
          {'You start with '}<b>{credits.total + ' credits'}</b>{'. On a weapon weigh '}<b>Damage</b>{', '}<b>Crit</b>{', '}
          <b>Range</b>{' and its qualities; on armour, '}<b>Soak</b>{' cuts damage while '}<b>Defence</b>{' adds setback dice to attackers.'}
          {/* F-100 surfacing K9 (R-SCC-6): the purse's because, after the sentence that says the purse (as drawn at 390) */}
          {fcBecauseSpans(credits.rows, 'data-creator-purse-why')}
        </p>
        {/* THE CITES ARE THE APP'S, NOT THE FRAME'S. The drawing carries two placeholder page
            numbers for the core book and neither is either rule's real printed page — the same
            class the motivation step's frame carried and the app's own history already rejected
            once. `fcStepCite` resolves both from `creator_step_cites.json`, and the desktop sheet
            has printed them all along (R-PGeC's head-cite row). */}
        {p.cite || p.encCite ? (
          <div style={{ marginTop: '11px' }}>
            {p.cite ? <span className="hp-cite" data-step-cite="starting_credits">{p.cite}</span> : null}
            {p.encCite ? <span className="hp-cite" data-step-cite="encumbrance" style={{ marginLeft: '7px' }}>{p.encCite}</span> : null}
          </div>
        ) : null}
      </div>
      {/* F-100 surfacing K7 (R-SCC-3): the entitlement under the plate that says the purse, as drawn at 390. */}
      <FCEntitlementPlate lines={p.entitlementLines} onToggle={p.onEntitlementToggle} />

      {/* THE TWO SPOKEN STATES, kept from the desktop sheet because they are the app's own law and
          the frame is silent on both: over budget and over the limit are SAID, never refused
          (`gear-concept` A1). The pill turns them red; these say what they mean. */}
      {overBudget ? (
        <span className="hp-none" data-gear-over-budget={-credits.remaining} style={{ display: 'block', marginTop: '11px' }}>
          {'You are over budget by ' + (-credits.remaining) + ' cr. Nothing is blocked \u2014 sell something back, or carry the debt and tell your GM.'}
        </span>
      ) : null}
      {overLimit ? (
        <span className="hp-none" data-gear-over-limit={enc.over} style={{ display: 'block', marginTop: '8px' }}>
          {'Over by ' + enc.over + ': ' + enc.setbacks + ' setback ' + (enc.setbacks === 1 ? 'die' : 'dice') + ' on Agility and Brawn checks'
            + (enc.freeManeuverLost ? ', and no free maneuver each turn.' : '.')}
        </span>
      ) : null}

      <div style={{ marginTop: '18px' }}>{fcGearDoor(p.onShop)}</div>
      {fcGearKitSechead(inv.length)}
      {fcGearKitPlate(inv, reg, p.onSell, true /* compact: the frame's three-span row */)}

      {/* SO FAR FOLDS on the phone — the frame makes it a `<details>` at the foot rather than a
          rail block there is no room for, the same idiom every sibling phone sheet carries. */}
      <details className="hp-unit">
        <summary>
          <div className="hp-head">
            <span className="hp-name">So Far</span>
            <span className="hp-glyph">{'\u25be'}</span>
          </div>
        </summary>
        <div className="hp-plate" data-pad="data" style={{ marginTop: '9px' }}>
          <table className="hp-ledger"><tbody className="hp-bands">
            {(p.soFar || []).map(function(r) {
              return (
                <tr key={r.k}>
                  <td className="hp-lkey">{r.k}</td>
                  <td className="hp-lval">{r.v ? r.v : <span className="hp-none">Not yet</span>}</td>
                </tr>
              );
            })}
          </tbody></table>
        </div>
      </details>
    </FCPhoneShell>
  );
}

function FCGearSheet(p) {
  // THE PHONE IS ITS OWN SHEET, not this one reflowed — see `FCGearSheetPhone`. Same branch
  // `FCCharSheet` takes, and the same reason: the frame gives the phone a status pill instead of
  // the rail's three plates, folds So Far into a `<details>`, and runs one column.
  if (p.band === 'mobile') return <FCGearSheetPhone {...p} />;
  var stepNo = (p.stepIndex == null) ? null : p.stepIndex + 1, stepTot = p.stepTotal || (p.steps || []).length;
  var inv = p.inventory || [], credits = p.credits || { total: 500, spent: 0, remaining: 500 };
  var reg = p.reg || null;
  var enc = fcGearEncumbrance(inv, reg, p.brawn, p.speciesEncDelta);
  var overBudget = credits.remaining < 0;
  var overLimit = !!(enc && enc.over > 0);
  var nextStep = (p.steps || [])[(p.stepIndex || 0) + 1];
  var nextLabel = nextStep && p.stepLabels ? p.stepLabels[nextStep] : 'the next step';
  var lines = inv.length;

  return (
    <div className="hpw-shell">
    <div className="hp-sheet hp-wide" data-doc-ground="creator" data-band={p.band} data-gear-step="1">

      <div className="hpw-bar">
        <div className="hp-runhead">
          <button type="button" onClick={p.onBack} data-creator-back="1"
            aria-label="Back to the previous step"
            style={{ background: 'none', border: 0, padding: 0, font: 'inherit', color: 'inherit', cursor: 'pointer' }}>
            <span>{'‹  Character Creation'}</span>
          </button>
          <span className="hp-folio">{fcFolio(stepNo, stepTot, p.stepName)}</span>
        </div>
      </div>

      <div className="hpw-grid hpw-grid-spend">

        {/* ── THE RAIL: Credits · Encumbrance · So Far · the commit. */}
        <div className="hpw-index hp-pane" style={{ gridArea: 'rail' }} data-creator-rail="1" data-rail-stack="1">
          <div className="hp-sechead" style={{ margin: '0 0 11px' }}><h2>Credits</h2></div>
          <div className="hp-plate" data-pad="data" data-rail-section="credits">
            <dl style={{ margin: 0 }}>
              <div className="hp-xp"><dt>Starting</dt><dd data-gear-starting={credits.total}>{credits.total + ' cr'}</dd>
                {fcBecauseSpans(credits.rows, 'data-creator-purse-why')}</div>
              <div className="hp-xp"><dt>Spent</dt><dd data-gear-spent={credits.spent}>{credits.spent + ' cr'}</dd></div>
              <div className="hp-xp" data-total="1">
                <dt>Left</dt>
                <dd data-creator-purse={credits.remaining}>{credits.remaining + ' cr'}</dd></div>
            </dl>
            {/* UNDRAWN — OVER BUDGET, a SPOKEN state (Addendum 1): the app's own line, where ruled. */}
            {overBudget ? (
              <span className="hp-none" data-gear-over-budget={-credits.remaining} style={{ display: 'block', marginTop: '8px' }}>
                {'You are over budget by ' + (-credits.remaining) + ' cr. Nothing is blocked — sell something back, or carry the debt and tell your GM.'}
              </span>
            ) : null}
          </div>
          {/* F-100 surfacing K7 (R-SCC-3): the entitlement under the Credits plate, as drawn. */}
          <FCEntitlementPlate lines={p.entitlementLines} onToggle={p.onEntitlementToggle} />
          <div className="hp-sechead" style={{ margin: '20px 0 10px' }}>
            <h2>Encumbrance</h2><span className="hp-cite">Brawn + 5</span></div>
          <div className="hp-plate" data-pad="data" data-rail-section="encumbrance">
            <dl style={{ margin: 0 }}>
              <div className="hp-xp" data-total="1">
                <dt>Carried</dt>
                <dd data-gear-carried={enc ? enc.carried : ''} data-gear-limit={enc ? enc.limit : ''}>
                  {enc ? enc.carried + ' of ' + enc.limit : '–'}</dd>
                {fcBecauseSpans(p.speciesEncRows, 'data-creator-enc-why')}</div>
            </dl>
            <p className="hp-prose hp-prose-sm" style={{ margin: '8px 0 0' }}>
              {'Over the limit is a '}<b>setback die</b>{' on Agility and Brawn checks for each point above, not a block.'}
            </p>
            {/* UNDRAWN — OVER THE LIMIT, spoken from the resolver's own figures. */}
            {overLimit ? (
              <span className="hp-none" data-gear-over-limit={enc.over} style={{ display: 'block', marginTop: '8px' }}>
                {'Over by ' + enc.over + ': ' + enc.setbacks + ' setback ' + (enc.setbacks === 1 ? 'die' : 'dice') + ' on Agility and Brawn checks'
                  + (enc.freeManeuverLost ? ', and no free maneuver each turn.' : '.')}
              </span>
            ) : null}
          </div>
          <div className="hp-sechead" style={{ margin: '20px 0 10px' }}><h2>So Far</h2></div>
          <div className="hp-plate" data-pad="data" data-rail-section="sofar">
            <table className="hp-ledger"><tbody className="hp-bands">
              {(p.soFar || []).map(function(r) {
                return (
                  <tr key={r.k}>
                    <td className="hp-lkey">{r.k}</td>
                    <td className="hp-lval">{r.v ? r.v : <span className="hp-none">Not yet</span>}</td>
                  </tr>
                );
              })}
            </tbody></table>
          </div>
          <div className="hp-railact" data-rail-section="commit">
            {/* NEVER GATED (Addendum 1): over budget and over the limit are spoken above, not refused here. */}
            <button type="button" className="hp-commit" data-creator-commit="1" onClick={p.onConfirm}>
              {(lines ? 'Continue to ' + nextLabel + ' ' : 'Continue without gear ')}<span>{'›'}</span>
            </button>
          </div>
        </div>

        {/* ── THE HEAD: the board's stephead pair, the lead, the line's two cites. */}
        <div className="hpw-head" style={{ gridArea: 'head', display: 'block' }}>
          {fcWaveNav(p)}
          <div className="hp-stephead">
            <div className="hp-stephead-title">
              <div style={{ display: 'flex', alignItems: 'center', gap: '11px' }}>
                <span className="hp-slash"><i /><i /><i /></span>
                <div className="hp-maker">{fcMakerLine(stepNo, stepTot)}</div>
              </div>
              <h1 className="hp-desig">{p.stepName}</h1>
              <div className="hp-desig-rule" />
            </div>
            <div className="hp-plate" data-pad="read"
              style={{ maxWidth: 'calc(var(--doc-lead-max, 640px) + 38px)' }}>
              <p className="hp-lead" data-step-standfirst="1" style={{ margin: 0 }}>
                {'You start with '}<b>{credits.total + ' credits'}</b>{'. On a weapon weigh '}<b>Damage</b>{', '}<b>Crit</b>{', '}
                <b>Range</b>{' and its qualities; on armour, '}<b>Soak</b>{' cuts damage while '}<b>Defence</b>{' adds setback dice to attackers.'}
              </p>
              {p.cite || p.encCite ? (
                <div style={{ marginTop: '11px' }}>
                  {p.cite ? <span className="hp-cite" data-step-cite="starting_credits">{p.cite}</span> : null}
                  {p.encCite ? <span className="hp-cite" data-step-cite="encumbrance" style={{ marginLeft: '7px' }}>{p.encCite}</span> : null}
                </div>
              ) : null}
            </div>
          </div>
        </div>

        {/* ── THE SPEND PANE: the door, then what came back through it. */}
        <div className="hpw-read hp-pane" style={{ gridArea: 'spend' }}>
          <div className="hp-spendwrap">
            {fcGearDoor(p.onShop)}
            {fcGearKitSechead(lines)}
            {fcGearKitPlate(inv, reg, p.onSell)}
          </div>
        </div>

      </div>
    </div>
    </div>
  );
}


/* ══════════════════════════════════════════════════════════════════════════════════════════════
   THE DECODER FAMILY — ONE EATER, ONE DRAWER (R3 Q2b; ruling item-dice-glyphs-r3 §3)

   OggDude description text carries two different kinds of bracket. They need two different
   answers, and for years this app fused them into one function that answered "delete it" to both.

     STRUCTURAL MARKUP   [H1]…[h1]  [p]  [br]  [B]…[b]     → the EATER removes it (it is layout)
     DICE-GLYPH TOKENS   [SE] [DI] [AD] [TR] …             → the DRAWER renders it (it is MECHANICS)

   THE EATER is `cleanMarkup` below. It must NEVER contain a `\[.*?\]` catch-all: that catch-all
   ran after the structural passes and swallowed every glyph token as collateral. It is the defect
   R3 exists to close — three copies of it deleted 2,144 item rows' dice symbols, and its fourth
   copy here was silently eating the 756 glyph tokens in talents.json.

   THE DRAWER is `glyphs` below — a 3-line adapter over the ONE shared `glyphText`
   (lib/shared/ui.jsx, exported on window.SWRPGUI), the same adapter lib/store/view.jsx,
   lib/shared/yardView.jsx and lib/shared/vesselView.jsx already use. CONSUMED, never copied.

   `renderDescription` — RETIRED HERE. It was the twin: the eater's structural passes and the
   drawer's token pass fused into one local function, kept in sync with `glyphText` by hand across
   two files. B-7 flagged the missing parity guard a month before R3; the whole R3 arc is the bill.
   Its 10 call sites now read `glyphs(cleanMarkup(x))` — the two jobs, named, in order, visibly
   separate. Do not re-fuse them into a third function; `test/decoder_family_parity.cjs` fails if
   `renderDescription` comes back.
   ══════════════════════════════════════════════════════════════════════════════════════════════ */

// THE EATER — structural markup only. NO `\[.*?\]`. NO glyph handling.
function cleanMarkup(text) {
  if (!text) return '';
  return text
    .replace(/\[H\d\].*?\[h\d\]\s*/gi, '')
    .replace(/\[p\]/gi, '\n')
    .replace(/\[br\]/gi, '\n')
    .replace(/\[B\](.*?)\[b\]/gi, '$1')
    .replace(/ +(\.(?![.\d])|[,;])/g, '$1')
    .replace(/^\s+/, '').trim();
}

// PROSE_GLYPH_SIZE — the em size the retired `renderDescription` passed to `symbolSpan`. Named and
// kept as this adapter's default so the twin's retirement is invisible to a reader: every one of
// its call sites drew at 1.3, and `glyphText`'s own default is 1.1.
var PROSE_GLYPH_SIZE = 1.3;

// THE DRAWER — consumed from its ONE home, window.SWRPGUI.glyphText (lib/shared/ui.jsx).
// Read off `window` at CALL time rather than the module-load destructure at the top of this file:
// it keeps the absent-renderer path real and exercisable (scripts/smoke_item_glyphs.py deletes the
// drawer at runtime and re-renders). DEGRADE RULE, matching the other three adapters: no drawer →
// the RAW STRING, never null. A missing renderer must not delete the description.
function glyphs(text, size, opts) {
  var U = window.SWRPGUI || {};
  return typeof U.glyphText === 'function' ? U.glyphText(text, size || PROSE_GLYPH_SIZE, opts) : text;
}
// B-1600 (ruling release-r7-bug-burndown ADDENDA 251, 276): the creator ground's prose callers pass this, so the
// derived board's `[data-doc-ground="creator"] .hp-sym` (1.02em) draws the glyph's box instead of an inline size.
// Only callers that render on that ground pass it; every other caller draws as before.
var CREATOR_GLYPHS = { cssSized: true };

// PLAIN-TEXT SINK PROJECTOR — for sinks that take a STRING and cannot host a React node. Removes
// EXACTLY the canonical `[XX]` token shape and nothing else; it is deliberately not `\[.*?\]`, so
// it can never grow into a fifth catch-all. JS mirror of
// `scripts/canonical/item_markup.strip_glyph_tokens`. Its callers:
//   · `pdfGlyphRuns` (below) — the printed sheet's dice projector, which matches every token the dice table knows and
//     prints it as a die (B-981, D-404 item 5); what reaches this function from there is only a token the table does
//     NOT know, removed as `glyphText` draws it on screen (nothing);
//   · the FFG form's `pdfText` — names and upgrades, and summaries whose rule carries no die (a form field holds one font);
//   · handleForcePowerBuy's persisted `.desc` — a save shape held byte-identical while the R-SY4 question of what a save
//     should store is with the architect (HOLD, not can't).
