// (R3 Q2b's "a PDF cannot draw a glyph" is retired: D-404 item 5 chose the dice font over spelling the die out.)
function plainTextGlyphless(text) {
  return String(text || '').replace(/\[[A-Z]{2}\]/g, '');
}

