async function generateFFGPdf(sheet, template) {
  var S1W = typeof pdfS1Words === 'function' ? pdfS1Words : function (text) { return text || ''; };   // S4; guarded: fixtures slice the exporter alone
  var PDFLib;
  try { PDFLib = await ensurePDFLib(); } catch(e) { throw pdfLoadFailure(e); }
  // R-M7G-9: the skill column and the CAREER box read the vocabulary — wait for it, so a blank means the registries
  // FAILED (the loader resolves null), never that they had not loaded yet.
  await loadCanonicalCharacterBuild();
  var sheetKey = sheet.book === 'aor' ? 'AoR' : sheet.book === 'fad' ? 'FaD' : 'EotE';
  var sheetFile = encodeURIComponent(sheetKey + ' Character Sheet (Form Fillable).pdf');

  var pdfBytes;
  // S5: the public copy's player brings the sheet (`template`, from sheetTemplateGet); holocron fetches its own, as before
  if (template && template.bytes) pdfBytes = template.bytes.slice(0);
  else try {
    var resp = await fetch('public/pdf/templates/' + sheetFile);
    if (!resp.ok) throw new Error(resp.statusText);
    pdfBytes = await resp.arrayBuffer();
  } catch (e) {
    throw pdfLoadFailure(e);
  }

  var pdfDoc = await PDFLib.PDFDocument.load(pdfBytes, { ignoreEncryption: true });
  var form = pdfDoc.getForm();
  var helvetica = await pdfDoc.embedFont(PDFLib.StandardFonts.Helvetica);
  var kit = await pdfSymbolKit(PDFLib, pdfDoc, helvetica);   // B-981: rule text keeps its dice
  // B-978 — NO SILENT FAILURES. Every intended write that fails is COUNTED by field name and reported
  // once at the end (`PDF export: …`). The empty catches here hid B-978 for the life of the exporter:
  // every talent row printed blank on every line and nothing said so. A field the template does not
  // carry is not written at all (B-979), so a name in this list is always a real miss.
  var failedWrites = [];
  // B-987: every text write is filtered to what Helvetica can encode (pdfEncodable), so updateFieldAppearances cannot throw.
  var set = function(name, val) { try { form.getTextField(name).setText(pdfEncodable(helvetica, val)); } catch(_) { failedWrites.push(name); } };
  var setSmall = function(name, val, fontSize) { try { var f = form.getTextField(name); f.setFontSize(fontSize || 7); f.setText(pdfEncodable(helvetica, val)); } catch(_) { failedWrites.push(name); } };
  var checkCB = function(name) { try { form.getCheckBox(name).check(); } catch(_) { failedWrites.push(name); } };
  // B-979 R4(c) (ruling release-r7-bug-burndown ADDENDUM 126): what a template CARRIES is read from the loaded form, never
  // typed by game line, the way talentRows is — so a template that gains a field gets its write.
  var fieldNames = form.getFields().map(function (f) { return f.getName(); });
  var hasField = function (name) { return fieldNames.indexOf(name) !== -1; };
  // B-979 (D-404 item 7): what the template has NO field for is not lost — each item is one line in NotableFeatures,
  // fitted by the talents' fitLine rule, written once at the end (below the Force powers). The presence tests above decide
  // which items; the player's own notable features follow them.
  var noBox = [];

  // ── Identity ──
  set('Name', sheet.name || '');
  set('Player', sheet.playerName || '');
  set('Species', sheet.species || '');
  set('Career', sheet.career || '');
  set('Specializations', sheet.specialization || '');

  // ── Appearance ──
  var ap = sheet.appearance || {};
  set('Age', ap.age || ''); set('Gender', ap.gender || '');
  set('Height', ap.height || ''); set('Build', ap.build || '');
  set('Hair', ap.hair || ''); set('Eyes', ap.eyes || '');

  // ── Characteristics ──
  var chars = sheet.characteristics || {};
  set('Brawn', chars.brawn || 2); set('Agility', chars.agility || 2);
  set('Intellect', chars.intellect || 2); set('Cunning', chars.cunning || 2);
  set('Willpower', chars.willpower || 2); set('Presence', chars.presence || 2);

  // ── Derived stats ── CS-2 (R-DAR): resolve-at-render, so the PDF matches the live sheet (incl. armor).
  var eq = resolveSheetEquipment(sheet.equipment, sheet);
  var derived = CharResolve.computeDerived(sheet, eq, window._canonicalCharbuild);   // B-23
  set('Soak', derived.soak || 0);
  set('MelDef', derived.meleeDefense || 0);
  set('RngDef', derived.rangedDefense || 0);
  set('WT', derived.woundThreshold || 0);
  set('ST', derived.strainThreshold || 0);
  // B-737 (b) — THE "Current" FIELDS CARRY THE SHEET'S CURRENT STATE, not the threshold again.
  // Both were `derived.*Threshold`, so a printed sheet reported the same number in both boxes no
  // matter how much damage the character was carrying. `sheet.currentWounds` / `sheet.currentStrain`
  // are what the sheet's two trackers write and what its own two readers read (`:26140-26141`,
  // `:32492-32493`). NEVER TOUCHED = THE KEY IS ABSENT: no record ships with either field (no
  // writer outside the trackers; `public/data/pregen_sheets.json` carries neither).
  //
  // B-746 / B-742 CLOSED IN DIRECTION (a) — THE FALLBACK IS 0, NOT THE THRESHOLD (Jason 2026-09-20).
  // B-737 kept the threshold here, and that left the printed sheet and the sheet on screen
  // disagreeing about the SAME blank case: the sheet's own two readers default an absent key to 0
  // (`:26147`, `:32499`) and this path printed the ceiling. Both tracks COUNT UP from nothing and
  // are clamped at threshold × 2, so a box named "Current" holding the threshold says the character
  // is at his wound threshold — Incapacitated (EotE CRB p.215; FaD CRB p.222) — which is the exact
  // opposite of an untouched character. All eighteen Quick Start records carry neither key, so every
  // printed pregen read as dying. The two boxes stay SEPARATE named form fields: the threshold in
  // `WT`/`ST`, the current value in `WT Current`/`ST Current`, never merged into one string.
  set('WT Current', sheet.currentWounds != null ? sheet.currentWounds : 0);
  set('ST Current', sheet.currentStrain != null ? sheet.currentStrain : 0);
  // B-979: only FaD's template carries a ForceRating field today; on EotE/AoR this write never landed.
  if (hasField('ForceRating')) set('ForceRating', derived.forceRating || 0);
  else if (derived.forceRating > 0) noBox.push('Force rating: ' + derived.forceRating);

  // ── XP, Credits, Encumbrance ──
  var xp = sheet.xp || {};
  set('Total XP', xp.total || '');
  set('Current XP', xp.remaining != null ? xp.remaining : (xp.total || ''));
  set('Credits', sheet.equipment ? sheet.equipment.credits : '');
  var enc = CharResolve.computeEncumbrance(eq, sheet.characteristics || {}, CharResolve.speciesEncumbranceDelta(sheet));
  // B-979: only EotE's template carries an Encumbrance field today; on AoR/FaD this write never landed.
  if (enc && hasField('Encumbrance')) set('Encumbrance', enc.carried + ' / ' + enc.limit);
  else if (enc) noBox.push('Encumbrance: ' + enc.carried + ' / ' + enc.limit);

  // ── Skills: rank pips + career checkboxes ──
  var skills = sheet.skills || {};
  var careerCBMap = PDF_CAREER_CB[sheetKey] || {};
  // B-1035 (F-100 M7 C2, R-M7K-7): the CAREER box means career — the one answer, CharResolve.careerSkillStatus —
  // never "trained" (it ticked every rank > 0 and missed every untrained career skill). No charbuild, no box: an
  // empty box is honest, a guessed one is not.
  var _pdfCb = (sheet && sheet.own && window.CharResolve.talentViewFor(sheet)) || window._canonicalCharbuild;   // F-100 M13 (R-M13L-13): sheetOwnViewOr's read, in place, as the PDF generator runs lifted out of this file
  var careerStatus = _pdfCb ? CharResolve.careerSkillStatus(sheet, _pdfCb) : {};
  Object.keys(PDF_SKILL_MAP).forEach(function(skillKey) {
    var pdfField = PDF_SKILL_MAP[skillKey];
    var rank = skills[skillKey] || 0;
    // Check rank pips
    for (var pip = 0; pip < 5; pip++) {
      if (pip < rank) checkCB(pdfField + '.' + pip);
    }
    if (careerStatus[skillKey] && careerCBMap[pdfField]) checkCB(careerCBMap[pdfField]);
  });

  // ── Weapons ──
  var RANGE_PDF = { Engaged:'Engaged', Short:'Short', Medium:'Medium', Long:'Long', Extreme:'Extreme' };
  var _eqR = eq;
  var weapons = _eqR.weapons || [];
  for (var wi = 0; wi < Math.min(weapons.length, 8); wi++) {
    var w = weapons[wi];
    var n = wi + 1;
    set('Weapon' + n, w.name || '');
    set('WeaponSkill' + n, w.skill || '');
    set('WeaponDamage' + n, w.damage || '');
    set('WeaponCrit' + n, critText(w.crit));
    set('WeaponRange' + n, RANGE_PDF[w.range] || w.range || '');
    var quals = w.qualities || '';
    set('WeaponSpecial' + n, quals.length > 60 ? quals.substring(0, 59) + '...' : quals);
  }

  // ── Armor → Weapons&Armor field ──
  var armor = _eqR.armor;
  if (armor) {
    var armorText = armor.name + ' Soak +' + (armor.soak || 0);
    setSmall('Weapons&Armor', armorText, 8);
  }

  // ── Gear ──
  var gear = (_eqR.gear || []).map(function(g) { return g.name + (g.qty > 1 ? ' ×' + g.qty : ''); });
  var gearText = gear.join('\n');
  if (sheetKey === 'AoR') {
    var mid = Math.ceil(gear.length / 2);
    setSmall('PersonalGear1', gear.slice(0, mid).join('\n'), 8);
    setSmall('PersonalGear2', gear.slice(mid).join('\n'), 8);
  } else {
    setSmall('PersonalGear', gearText, 8);
  }

  // ── Narrative Mechanic ──
  if (sheetKey === 'EotE' && sheet.obligation) {
    set('Obligation1', (sheet.obligation.type || '').toUpperCase ? mechTypeName(await SWRPGMechTypeNames.load(qbFetchJson), 'obligation', sheet.obligation.type) : '');   // B-1605
    set('Magnitude1', sheet.obligation.value || '');
    if (sheet.obligation.description) setSmall('ObligationDesc1', sheet.obligation.description, 6);
  } else if (sheetKey === 'AoR' && sheet.duty) {
    set('Duty1', mechTypeName(await SWRPGMechTypeNames.load(qbFetchJson), 'duty', sheet.duty.type || ''));   // B-1605
    set('Magnitude1', sheet.duty.value || '');
  } else if (sheetKey === 'FaD') {
    if (sheet.morality) {
      set('EmotionalStrength', sheet.morality.strength || sheet.morality.type || '');
      set('EmotionalWeakness', sheet.morality.weakness || '');
      set('Morality', sheet.morality.value || 50);
      set('Conflict', 0);
    }
  }

  // ── Motivations ──
  var mot = sheet.motivations || {};
  if (mot.desire || mot.strength) {
    set('Motivation1', mot.desire || mot.strength || '');
    var motDesc = [];
    if (mot.desire) motDesc.push('Desire: ' + mot.desire);
    if (mot.fear) motDesc.push('Fear: ' + mot.fear);
    if (mot.strength) motDesc.push('Strength: ' + mot.strength);
    if (mot.flaw) motDesc.push('Flaw: ' + mot.flaw);
    setSmall('Mot1Desc', motDesc.join(', '), 6);
  }

  // ── Backstory → BackgroundNotes or NotableFeatures ──
  // B-979: only EotE's template carries BackgroundNotes today; on AoR/FaD this write never landed.
  if (sheet.backstory && hasField('BackgroundNotes')) setSmall('BackgroundNotes', sheet.backstory, 7);
  else if (sheet.backstory) noBox.push('Backstory: ' + sheet.backstory);

  // ── Talents + Force powers (B-978) ──
  // Each talent row is a non-terminal PARENT `TalentNN` over three terminal text fields: `.0` NAME,
  // `.1` PAGE #, `.2` ABILITY SUMMARY. The old loop wrote the parent, which pdf-lib cannot resolve, so
  // every row printed blank on every line. The row and slot counts are READ from the loaded template
  // (EotE 28 rows, AoR 14, FaD 12; FaD alone has 3 Force-power slots), never a literal. When a
  // character owns more than fit, the last row says how many are not shown instead of dropping them.
  var countOf = function (re) {
    var seen = {};
    fieldNames.forEach(function (n) { var m = re.exec(n); if (m) seen[m[1]] = true; });
    return Object.keys(seen).length;
  };
  var talentRows = countOf(/^Talent(\d\d)\.\d$/);
  var powerSlots = countOf(/^ForcePower(\d\d)$/);
  var num2 = function (i) { return (i < 10 ? '0' : '') + i; };
  var overflowNote = function (n) { return '+' + n + ' more: see Holocron'; };
  // A form field holds ONE font, so a field cannot carry a die. pdfText is for text with none (names, upgrades, and every
  // summary whose rule has no die): the tokens it meets are unknown ones (plainTextGlyphless), and a character Helvetica
  // cannot encode is dropped (pdfEncodable, B-987's one filter). A summary WITH a die goes to drawRuns below (B-981).
  var pdfText = function (s) {
    return pdfEncodable(helvetica, plainTextGlyphless(s).replace(/\s+/g, ' ').trim());
  };
  var boxWidth = function (name) {
    try { return form.getTextField(name).acroField.getWidgets()[0].getRectangle().width - 4; } catch (_) { return 0; }
  };
  var boxHeight = function (name) {
    try { return form.getTextField(name).acroField.getWidgets()[0].getRectangle().height - 4; } catch (_) { return 0; }
  };
  var fits = function (s, width, size) { return helvetica.widthOfTextAtSize(s, size) <= width; };
  // Trim to the box at `size`, word by word, ending in an ellipsis.
  var fitLine = function (s, width, size) {
    if (fits(s, width, size)) return s;
    var words = s.split(' ');
    while (words.length > 1 && !fits(words.join(' ') + '…', width, size)) words.pop();
    var out = words.join(' ');
    while (out.length && !fits(out + '…', width, size)) out = out.slice(0, -1);
    return out.replace(/[\s,;:.]+$/, '') + '…';
  };
  var wrapLines = function (s, width, size) {
    var lines = [], cur = '';
    s.split(' ').forEach(function (w) {
      var next = cur ? cur + ' ' + w : w;
      if (cur && !fits(next, width, size)) { lines.push(cur); cur = w; } else cur = next;
    });
    if (cur) lines.push(cur);
    return lines;
  };
  var SUMMARY_PT = 7;
  // B-981 (D-404 item 5): a summary whose rule carries a die is DRAWN on the page inside the field's own box, through the
  // one projector (pdfGlyphRuns → kit), and the field is left empty and read-only so nothing types over it. Every field
  // without a die keeps the form write above, byte for byte.
  var drawRuns = function (name, lines, size) {
    try {
      var field = form.getTextField(name);
      var widget = field.acroField.getWidgets()[0];
      var r = widget.getRectangle();
      var page = pdfDoc.findPageForAnnotationRef(pdfDoc.context.getObjectRef(widget.dict));
      var lh = helvetica.heightAtSize(size);
      var y = lines.length === 1 && r.height < lh * 2 ? r.y + (r.height - size) / 2 + size * 0.22 : r.y + r.height - 2 - size;
      var align = field.getAlignment();   // the field's own quadding: EotE's talent column is right-aligned
      lines.forEach(function (line) {
        var w = kit.width(line, size);
        var x = align === PDFLib.TextAlignment.Right ? r.x + r.width - 2 - w : align === PDFLib.TextAlignment.Center ? r.x + (r.width - w) / 2 : r.x + 2;
        kit.draw(page, line, x, y, size, PDFLib.rgb(0, 0, 0));
        y -= lh;
      });
      field.setText('');
      field.enableReadOnly();
    } catch (_) { failedWrites.push(name); }
  };

  // R-SSC-7 (frame P2): each standing signature ability joins the talents box as "<name> (Signature)" with its words — DARK
  // (sheetSignatureEntries is [] with M12's engine key OFF); the form has no footnote room, so it prints no because notes.
  var talents = sheetTalentsForDisplay(sheet).concat(sheetSignatureEntries(sheet).filter(function (e) { return e.ok; })
    .map(function (e) { return { name: e.name + ' (Signature)', ranked: false, description: S1W(e.words, 'signature', e, sheet) }; }));
  var talentsShown = talents.length > talentRows ? talentRows - 1 : talents.length;
  for (var ti = 0; ti < talentsShown; ti++) {
    var t = talents[ti];
    var trow = 'Talent' + num2(ti + 1);
    set(trow + '.0', pdfText(t.name + (t.ranked ? ' ' + (t.rank || 1) : '')));
    var tdesc = S1W(t.description, 'talent', t, sheet);   // S4 (a signature entry's words were resolved above)
    var truns = pdfGlyphRuns(tdesc);
    if (kit.hasSym(truns)) drawRuns(trow + '.2', [kit.fit(truns, boxWidth(trow + '.2'), SUMMARY_PT)], SUMMARY_PT);
    else {
      var tsum = pdfText(tdesc);
      if (tsum) setSmall(trow + '.2', fitLine(tsum, boxWidth(trow + '.2'), SUMMARY_PT), SUMMARY_PT);
    }
  }
  if (talents.length > talentRows && talentRows > 0) set('Talent' + num2(talentRows) + '.0', overflowNote(talents.length - talentsShown));

  // FaD's three power slots: the name in `ForcePowerNN`, the summary and bought upgrades in `_Desc`.
  // The upgrades are kept whole and the summary gives way to them when the box is full.
  var powers = powerSlots ? sheetForcePowersForDisplay(sheet) : [];
  var powersShown = powers.length > powerSlots ? powerSlots - 1 : powers.length;
  var DESC_PT = 8;
  for (var pi = 0; pi < powersShown; pi++) {
    var fp = powers[pi];
    var slot = 'ForcePower' + num2(pi + 1);
    set(slot, pdfText(fp.name || ''));
    var counts = {}, order = [];
    (fp.upgradeNames || fp.upgrades || []).forEach(function (u) {
      if (!counts[u]) { counts[u] = 0; order.push(u); }
      counts[u]++;
    });
    var upText = order.length ? pdfText('Upgrades: ' + order.map(function (u) { return u + (counts[u] > 1 ? ' ×' + counts[u] : ''); }).join(', ')) : '';
    var dw = boxWidth(slot + '_Desc');
    var maxLines = Math.max(1, Math.floor(boxHeight(slot + '_Desc') / helvetica.heightAtSize(DESC_PT)));
    var upLines = upText ? wrapLines(upText, dw, DESC_PT) : [];
    var room = Math.max(0, maxLines - upLines.length);
    var fpDesc = S1W(fp.description, 'force', fp, sheet);   // S4
    var fpRuns = pdfGlyphRuns(fpDesc);
    if (kit.hasSym(fpRuns)) {   // B-981: the same rule over runs, drawn in the box
      var sumRuns = kit.wrap(fpRuns, dw, DESC_PT);
      if (sumRuns.length > room) {
        sumRuns = sumRuns.slice(0, room);
        if (room) sumRuns[room - 1] = kit.fit(sumRuns[room - 1].concat([{ text: '…' }]), dw, DESC_PT);
      }
      drawRuns(slot + '_Desc', sumRuns.concat(upLines.map(function (l) { return [{ text: l }]; })), DESC_PT);
      continue;
    }
    var sumLines = wrapLines(pdfText(fpDesc), dw, DESC_PT);
    if (sumLines.length > room) {
      sumLines = sumLines.slice(0, room);
      if (room) sumLines[room - 1] = fitLine(sumLines[room - 1] + '…', dw, DESC_PT);
    }
    setSmall(slot + '_Desc', sumLines.concat(upLines).join('\n'), DESC_PT);
  }
  if (powers.length > powerSlots && powerSlots > 0) set('ForcePower' + num2(powerSlots), overflowNote(powers.length - powersShown));
  if (!powerSlots) {
    var unboxedPowers = sheetForcePowersForDisplay(sheet).map(function (p) { return p.name; }).filter(Boolean);
    if (unboxedPowers.length) noBox.push('Force powers: ' + unboxedPowers.join(', '));
  }

  // B-979: the NotableFeatures box — the template's homeless items, one fitted line each, then the player's own words.
  var notable = noBox.map(function (l) { return fitLine(pdfText(l), boxWidth('NotableFeatures'), 7); });
  if (kit.keyLine()) notable.push('Key: ' + kit.keyLine());   // T3: once, when a die printed as words
  if (sheet.notableFeatures) notable.push(sheet.notableFeatures);
  if (notable.length) setSmall('NotableFeatures', notable.join('\n'), 7);

  if (failedWrites.length) {
    console.warn('PDF export: ' + failedWrites.length + ' field write(s) failed on the ' + sheetKey + ' template: ' + failedWrites.join(', '));
  }

  // Update field appearances with embedded font
  form.updateFieldAppearances(helvetica);

  return await pdfDoc.save();
}


// B-1594 (D-411 items 17–18): a failed PDF never opens a browser dialog. The exporters THROW, and a failed load (pdf-lib, or
// the FFG template) is tagged 'load'; anything else that throws while the file is made is 'make'. downloadCharacterPDF
// RETURNS the cause ('load' | 'make', null when the file was handed over) and the sheet draws it (SheetPaper's PDF line).
function pdfLoadFailure(e) {
  var err = e instanceof Error ? e : new Error(String(e));
  err.pdfCause = 'load';
  return err;
}
var PDF_LOAD_LINE = 'The PDF couldn\u2019t load. Check your connection, then retry.';
var PDF_MAKE_LINE = 'This character\u2019s PDF couldn\u2019t be made.';

// S5 (argo-a1-curation ADDENDUM 4; argo-a1-export-fields D7; mockup F8): BRING YOUR OWN SHEET. The public copy ships no FFG
// sheet, so the player chooses their own form-fillable PDF, once per game line. It is kept on this device only: IndexedDB
// `swrpg_sheet_templates`, store `sheets`, key = game line (eote · aor · fad), value {line, name, size, sha256, saved_at,
// bytes}. Only the exporter reads it; it is never synced, backed up (backup.js reads only the databases it names) or
// uploaded. Asked only in a copy whose book text was removed (S6); holocron.work never opens the database.
var SHEET_LINES = {
  // `fields`: the right-sheet test's AcroForm names — two every sheet carries, and one only that line's sheet has
  eote: { name: 'Edge of the Empire', fields: ['Name', 'Career', 'Obligation1'] },
  aor: { name: 'Age of Rebellion', fields: ['Name', 'Career', 'Duty1'] },
  fad: { name: 'Force and Destiny', fields: ['Name', 'Career', 'ForcePower01'] },
};
function sheetTemplateLine(sheet) { return sheet && sheet.book === 'aor' ? 'aor' : sheet && sheet.book === 'fad' ? 'fad' : 'eote'; }
function sheetTemplatesAsked() { var S = window.SWRPGSources; return !!(S && S.bookTextRemoved && S.bookTextRemoved()); }
function sheetTemplatesDb() {
  var DB_NAME = 'swrpg_sheet_templates';   // named so scripts/release_store_census.py resolves the store (R-R3N-6)
  return new Promise(function (res, rej) {
    var rq;
    try { rq = indexedDB.open(DB_NAME, 1); } catch (e) { rej(e); return; }
    rq.onupgradeneeded = function () { if (!rq.result.objectStoreNames.contains('sheets')) rq.result.createObjectStore('sheets', { keyPath: 'line' }); };
    rq.onsuccess = function () { res(rq.result); };
    rq.onerror = function () { rej(rq.error); };
  });
}
function sheetTemplateGet(line) {
  return sheetTemplatesDb().then(function (db) {
    return new Promise(function (res) {
      var rq = db.transaction('sheets', 'readonly').objectStore('sheets').get(line);
      rq.onsuccess = function () { res(rq.result || null); };
      rq.onerror = function () { res(null); };
    });
  }).catch(function () { return null; });
}
function sheetTemplatePut(value) {
  return sheetTemplatesDb().then(function (db) {
    return new Promise(function (res, rej) {
      var tx = db.transaction('sheets', 'readwrite');
      tx.objectStore('sheets').put(value);   // Change sheet replaces the line's entry
      tx.oncomplete = function () { res(value); };
      tx.onerror = function () { rej(tx.error); };
    });
  });
}
// the right-sheet test (D7, mechanics): pdf-lib opens the file, and the line's AcroForm fields are present
async function sheetTemplateFits(bytes, line) {
  var PDFLib;
  try { PDFLib = await ensurePDFLib(); } catch (e) { throw pdfLoadFailure(e); }
  try {
    var doc = await PDFLib.PDFDocument.load(bytes.slice(0), { ignoreEncryption: true });
    var names = doc.getForm().getFields().map(function (f) { return f.getName(); });
    return SHEET_LINES[line].fields.every(function (n) { return names.indexOf(n) !== -1; });
  } catch (e) { return false; }
}
// a chosen file → the stored entry, or null when it is not the line's sheet
async function sheetTemplateFromFile(file, line) {
  var bytes = await file.arrayBuffer();
  if (!(await sheetTemplateFits(bytes, line))) return null;
  var dig = await crypto.subtle.digest('SHA-256', bytes);
  var hex = Array.prototype.map.call(new Uint8Array(dig), function (b) { return ('0' + b.toString(16)).slice(-2); }).join('');
  return sheetTemplatePut({ line: line, name: file.name, size: file.size, sha256: hex, saved_at: new Date().toISOString(), bytes: bytes });
}

async function downloadCharacterPDF(sheet, template) {
  try {
    var pdfBytes = COMMERCIAL_MODE ? await generateCustomPdf(sheet) : await generateFFGPdf(sheet, template);
    var blob = new Blob([pdfBytes], { type: 'application/pdf' });
    var url = URL.createObjectURL(blob);
    var baseName = (sheet.name || 'character').replace(/[^a-zA-Z0-9]/g, '_');
    var filename = baseName + '_Sheet.pdf';
    var isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
    if (isMobile) {
      window.open(url, '_blank');
      setTimeout(function() { URL.revokeObjectURL(url); }, 10000);
    } else {
      var a = document.createElement('a');
      a.href = url; a.download = filename;
      document.body.appendChild(a); a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }
    // B-715 (D-404 item 8): the PDF button downloads the PDF and nothing else. It used to write a second
    // `swrpg-character-sheet` JSON beside it that no product path reads back; the whole-save backup is the one
    // file that restores (D-252/D-258).
    return null;
  } catch (e) {
    console.error('PDF generation failed:', e);
    return e && e.pdfCause === 'load' ? 'load' : 'make';
  }
}

/* ══════════════════════════════════════════════════════
   CHARACTER SHEET — FFG-inspired 3-page swipeable viewer
══════════════════════════════════════════════════════ */

const SKILL_NAMES = {
  ASTRO:'Astrogation',ATHL:'Athletics',BRAWL:'Brawl',CHARM:'Charm',COERC:'Coercion',
  COMP:'Computers',COOL:'Cool',COORD:'Coordination',DECEP:'Deception',DISC:'Discipline',
  GUNN:'Gunnery',KNOWCORE:'Core Worlds',KNOWED:'Education',KNOWLORE:'Lore',
  KNOWOUT:'Outer Rim',KNOWUND:'Underworld',KNOWWARF:'Warfare',KNOWXENO:'Xenology',
  LEAD:'Leadership',LTSAB:'Lightsaber',MECH:'Mechanics',MED:'Medicine',MELEE:'Melee',
  NEGOT:'Negotiation',PERCEP:'Perception',PILPLAN:'Piloting (Planetary)',
  PILSP:'Piloting (Space)',RANGHVY:'Ranged (Heavy)',RANGLT:'Ranged (Light)',
  RESIL:'Resilience',SKULL:'Skulduggery',STEAL:'Stealth',STREET:'Streetwise',
  SURV:'Survival',VIGIL:'Vigilance',
};

// F-46 dc3 v3: the FFG skill categories, for the cockpit's segmented skills toggle (TRAINED/GENERAL/
// COMBAT/KNOWLEDGE). Combat = the 6 attack skills; Knowledge = the KNOW* keys; General = the rest.
var COMBAT_SKILL_KEYS = { BRAWL:1, GUNN:1, LTSAB:1, MELEE:1, RANGHVY:1, RANGLT:1 };
function skillCategoryOf(key) {
  if (/^KNOW/.test(key)) return 'KNOWLEDGE';
  if (COMBAT_SKILL_KEYS[key]) return 'COMBAT';
  return 'GENERAL';
}

var h = React.createElement;

// ══════════════════════════════════════════════════════
// Styling primitives — ported from gm.html so the
// Player Datapad sheet matches the NPC reference voice.
// Keep these at the top of the sheet layer; every page
