function CharacterSheet({ char, sheet, onBack, onSave, isSaved, onOpenStore, onOpenYard, onSheetChange, writeCharacter, onOpenModify, qualitiesDb, chromePinned, onSummonChrome }) {
  var accent = char.accent || '#F5C842';
  // Portrait state — the paper PROFILE unit sets it (onPortrait); the spine and the unit read portraitSrc.
  // R-B1: hydrate from a PERSISTED uploaded portrait (a data: URL on the record) so a
  // custom portrait survives reload — incl. COMMERCIAL_MODE, where portraitSrc shows only
  // customPortrait. Pregen asset-path portraits stay null here (commercial hides them).
  // B-931 (ruling `paper-b931` R-PB9-4): read through the ONE fold, over the pair the sheet was handed — a `data:`
  // URI first, then any value; `selectedChar` before the sheet. The openers fold the record into the sheet, so on
  // any opened record this is `sheet.portrait`; the order only matters for a pair that did not come through one.
  var _storedPortrait = window.SWRPGRecordPortrait.recordPortraitOf({ selectedChar: char, sheetData: sheet });
  function _persistedPortrait() {
    return _storedPortrait.indexOf('data:') === 0 ? _storedPortrait : null;
  }
  var _cp = useState(_persistedPortrait()), customPortrait = _cp[0], setCustomPortrait = _cp[1];
  // R-B1: route portrait changes through the saved record (write-through), not just local state.
  function persistPortrait(v) { setCustomPortrait(v); if (onSheetChange) onSheetChange({ portrait: v || '' }); }
  var portraitSrc = customPortrait || (COMMERCIAL_MODE ? '' : _storedPortrait);

  // F-87 — the DICE HUB's open state. Deliberately CharacterSheet-level and nothing more: the hub
  // is an overlay STATE of this screen, never a route (D-DH-6), so it needs no URL, no history
  // entry and no persistence. Closing unmounts it, which is also what makes the band chip's
  // ephemerality structural rather than a promise (R-DRB-2).
  var _hub = React.useState(false), hubOpen = _hub[0], setHubOpen = _hub[1];

  // The open unit, by LABEL: 'OVERVIEW' (the default, the first unit) or a label the yard's jump names
  // ('VESSELS'). SheetPaper maps a label to its unit — the one home of that vocabulary.
  var pageState = useState(function() { var p = null; try { p = sessionStorage.getItem('_yard_jump_page'); } catch(e){} return p || 'OVERVIEW'; });
  useEffect(function() { try { sessionStorage.removeItem('_yard_jump_page'); } catch(e){} }, []);

  // THE PAPER SHEET — the one face since N-post (lap paper-sheet-delete): the old face, its switch and
  // its TABLE MODE are deleted.
  return h(SheetPaper, {
    sheet: sheet, char: char, accent: accent, portraitSrc: portraitSrc, onPortrait: persistPortrait,
    openLabel: pageState[0], onOpen: function (label) { pageState[1](label); },
    hubOpen: hubOpen, setHubOpen: setHubOpen, chromePinned: chromePinned, onSummonChrome: onSummonChrome,   // B-629: the paper sheet IS the table; no toggle
    onBack: onBack, onSave: onSave, isSaved: isSaved, onOpenStore: onOpenStore, onSheetChange: onSheetChange, onOpenModify: onOpenModify,
    qualitiesDb: qualitiesDb, onOpenYard: onOpenYard, writeCharacter: writeCharacter,
  });
}

