/* ══════════════════════════════════════════════════════
   TEST-BED GENERATOR SCREEN — dev-only, runs SWRPGTestBed
   and downloads 12 PC JSONs + a manifest.
   Accessed via /player?testbed (or legacy /player.html?testbed which 301s)
══════════════════════════════════════════════════════ */
function TestBedScreen() {
  const [gameData, setGameData] = useState(null);
  const [status, setStatus] = useState('idle');
  const [results, setResults] = useState([]);
  const [error, setError] = useState(null);

  useEffect(function() {
    Promise.all([loadQuickBuildData(), loadCanonicalRegistries(), loadCanonicalCharacterBuild()])
      .then(function(res) {
        if (!res[1] || !res[2]) { setError('Failed to load game data: canonical registries unavailable'); return; }
        setGameData({ charbuild: res[2], narrativeMechanics: res[0].narrativeMechanics, canonical: res[1] });
      })
      .catch(function(e) { setError('Failed to load game data: ' + e.message); });
  }, []);

  function triggerDownload(name, contents, mime) {
    const blob = new Blob([contents], { type: mime });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  function handleGenerateAll() {
    if (!gameData) return;
    setStatus('generating');
    setError(null);
    try {
      const out = window.SWRPGTestBed.generateAll(gameData);
      const report = out.map(function(r) {
        if (r.error) return { id: r.spec.id, error: r.error };
        return {
          id: r.spec.id,
          name: r.result.sheet.name,
          species: r.result.sheet.species,
          career: r.result.sheet.career,
          tier: r.spec.tier,
          xp_total: r.result.sheet.xp.total,
          xp_remaining: r.result.sheet.xp.remaining,
        };
      });
      setResults(report);

      // Bundle everything into ONE JSON file to avoid browser multi-download
      // rate limits. Consumer scripts split this into individual PC files.
      const bundle = {
        schema: 'swrpg-test-bed-bundle',
        schema_version: 1,
        generated_at: new Date().toISOString(),
        count: out.filter(function(r) { return !r.error; }).length,
        errors: out.filter(function(r) { return r.error; }).map(function(r) { return { id: r.spec.id, error: r.error }; }),
        pcs: out.filter(function(r) { return !r.error; }).map(function(r) {
          return {
            id: r.spec.id,
            tier: r.spec.tier,
            name: r.result.sheet.name,
            species: r.result.sheet.species,
            career: r.result.sheet.career,
            file: r.spec.id + '_' + r.result.sheet.name.replace(/[^a-zA-Z0-9]/g, '_') + '.json',
            payload: {
              schema: 'swrpg-character-sheet',
              schema_version: 1,
              test_bed: { id: r.spec.id, tier: r.spec.tier },
              exported_at: new Date().toISOString(),
              sheet: r.result.sheet,
              character: r.result.character,
            },
          };
        }),
      };
      triggerDownload('swrpg_test_bed_bundle.json', JSON.stringify(bundle, null, 2), 'application/json');
      setStatus('done');
    } catch (e) {
      setError(String(e));
      setStatus('error');
    }
  }

  function handleDownloadSingle(specId) {
    if (!gameData) return;
    setError(null);
    try {
      const r = window.SWRPGTestBed.generateOne(specId, gameData);
      const baseName = specId + '_' + r.sheet.name.replace(/[^a-zA-Z0-9]/g, '_');
      const payload = {
        schema: 'swrpg-character-sheet',
        schema_version: 1,
        test_bed: { id: specId, tier: window.SWRPGTestBed.specs.find(function(s) { return s.id === specId; }).tier },
        exported_at: new Date().toISOString(),
        sheet: r.sheet,
        character: r.character,
      };
      triggerDownload(baseName + '.json', JSON.stringify(payload, null, 2), 'application/json');
    } catch (e) {
      // B-1594: the failure is drawn in this screen's own error line (GENERATE ALL's), never a browser dialog.
      setError('Generate failed: ' + e.message);
    }
  }

  const tierColors = { beginner: '#4ECB71', mid: '#FFC857', late: '#FF5555' };
  const specs = (window.SWRPGTestBed && window.SWRPGTestBed.specs) || [];

  return React.createElement('div', {
    style: {
      position: 'absolute', inset: 0, background: '#050c18', color: '#fff',
      fontFamily: 'var(--font-body)', overflow: 'auto', padding: '24px 20px',
    }
  },
    React.createElement('div', { style: { maxWidth: 720, margin: '0 auto' } },
      React.createElement('div', { style: { fontFamily: 'var(--font-display)', fontSize: 'var(--fs-lg)', letterSpacing: '0.2em', color: '#F5C842', marginBottom: 8 } }, 'TEST BED GENERATOR'),
      React.createElement('div', { style: { fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-xs)', letterSpacing: '0.14em', color: 'rgba(255,255,255,0.4)', marginBottom: 24 } }, 'DEV-ONLY · /player?testbed'),
      error && React.createElement('div', { style: { padding: 12, background: 'rgba(255,80,80,0.1)', border: '1px solid rgba(255,80,80,0.4)', borderRadius: 6, marginBottom: 16, fontSize: 'var(--fs-sm)', color: '#FF8A8A' } }, error),
      !gameData && !error && React.createElement('div', { style: { padding: 16, background: 'rgba(255,255,255,0.04)', borderRadius: 6, fontSize: 'var(--fs-sm)', color: 'rgba(255,255,255,0.5)' } }, 'Loading game data…'),
      gameData && React.createElement('div', null,
        React.createElement('div', { style: { display: 'flex', gap: 8, marginBottom: 24 } },
          React.createElement('button', {
            onClick: handleGenerateAll,
            disabled: status === 'generating',
            style: {
              flex: 1, padding: '14px', background: 'linear-gradient(135deg, #F5C84222, #F5C84208)',
              border: '1px solid #F5C84266', borderRadius: 8, cursor: 'pointer',
              fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 'var(--fs-sm)', letterSpacing: '0.14em',
              color: '#F5C842', textShadow: '0 0 10px #F5C84288',
            }
          }, status === 'generating' ? 'GENERATING…' : 'GENERATE ALL 12 (BUNDLE) ▶'),
        ),
        React.createElement('div', { style: { fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-2xs)', letterSpacing: '0.18em', color: 'rgba(255,255,255,0.35)', marginBottom: 8 } }, 'INDIVIDUAL PCS'),
        React.createElement('div', { style: { display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 6, marginBottom: 24 } },
          specs.map(function(s) {
            return React.createElement('button', {
              key: s.id,
              onClick: function() { handleDownloadSingle(s.id); },
              style: {
                padding: '10px 12px', textAlign: 'left',
                background: 'rgba(255,255,255,0.03)',
                border: '1px solid ' + (tierColors[s.tier] || '#666') + '33',
                borderLeft: '3px solid ' + (tierColors[s.tier] || '#666'),
                borderRadius: 4, cursor: 'pointer',
                fontFamily: 'var(--font-body)', fontSize: 'var(--fs-sm)', color: '#fff',
              }
            },
              React.createElement('div', { style: { fontWeight: 700 } }, s.id + ' · ' + s.name),
              React.createElement('div', { style: { fontSize: 'var(--fs-xs)', color: 'rgba(255,255,255,0.5)', marginTop: 2 } }, s.tier + ' · ' + s.speciesKey + ' · ' + s.careerName),
            );
          })
        ),
        results.length > 0 && React.createElement('div', null,
          React.createElement('div', { style: { fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-2xs)', letterSpacing: '0.18em', color: 'var(--text-success)', marginBottom: 8 } }, '✓ LAST RUN (' + results.length + ' files)'),
          React.createElement('div', { style: { fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-xs)', color: 'rgba(255,255,255,0.6)', lineHeight: 1.7 } },
            results.map(function(r) {
              return React.createElement('div', { key: r.id },
                r.error ? (r.id + ': ERROR — ' + r.error) :
                (r.id + ' [' + r.tier + '] ' + r.name + ' · ' + r.species + ' ' + r.career + ' · ' + r.xp_remaining + '/' + r.xp_total + ' XP')
              );
            })
          )
        )
      )
    )
  );
}

/* ══════════════════════════════════════════════════════
   PROFILE FORK (Tutorial Layer 0)
   Single profile written on first launch, then a welcome
   fork (BEGIN TOUR / EXPLORE ON MY OWN). BEGIN TOUR opts into
   the in-context coach marks; the deep teaching is the Full
   Creator walkthrough (Docs/TUTORIAL_DIRECTION.md). The old
   standalone OVERVIEW slideshow was retired 2026-06-15.
══════════════════════════════════════════════════════ */
const PROFILE_STORAGE_KEY = 'swrpg_profile_v1';

function readProfile() {
  try {
    var raw = localStorage.getItem(PROFILE_STORAGE_KEY);
    if (!raw) return null;
    var p = JSON.parse(raw);
    return p;
  } catch (e) { return null; }
}
function writeProfile(p) {
  try { localStorage.setItem(PROFILE_STORAGE_KEY, JSON.stringify(p)); } catch (e) {}
}
// (WelcomeModal + TutorialHub REMOVED — nav Phase 4. The launchpad is the front door; the in-context
//  creation coach marks stay; the Ko-fi support link moved to the launchpad footer.)

function pathForScreen(screenId, opts) {
  var charId = opts && opts.charId;
  switch (screenId) {
    case 'landing':       return '/player';
    case 'pregen':        return '/player/pregen';
    case 'quickbuild':    return '/player/quickbuild';
    case 'custom':        return '/player/custom';
    case 'sheet':         return charId ? '/player/sheet/' + charId : '/player/sheet';
    case 'store':         return charId ? '/player/sheet/' + charId + '/store' : '/player/store';
    case 'modify':        return '/player/sheet/' + charId + '/modify';   // F-100 M13 R-M13B-2: optional ?section=<key>; navTo appends it
    case 'yard':          return (opts && opts.vehicleKey) ? '/player/yard/' + opts.vehicleKey : '/player/yard';  // R-Y2-2 front door
    case 'npc':           return '/player/npc' + ((opts && opts.npcPath) ? '/' + opts.npcPath : '');   // B-863
    case 'import':        return '/player/import';   // OGG-1 import surface
    case 'backup':        return '/player/backup';   // RELEASE R3 (D-258): the whole-save backup
    case 'homebrew':      return '/player/homebrew';   // F-100 C2 (R-FIEC-5); reached only while swrpg_homebrew_editor is on
    default:              return '/player';
  }
}

// The screen a cold load opens (PlayerApp's initial screen) — module scope since B-139, so the boot can load that
// screen's parts before the first render.
function playerBootScreen() {
  if (homebrewScreenFor(window.location.pathname)) return 'homebrew';   // F-100 C2 (null while the switch is off)
  if (yardScreenFor(window.location.pathname) != null) return 'yard';   // SHIP YARD S4 · K6
  var parsed = parsePathToScreen(window.location.pathname);
  if (parsed.screen) return parsed.screen;
  // Visitors land on the landing (the WelcomeModal was removed in nav Phase 4 — the launchpad is the
  // front door). A returning player is not routed past it (R-LFM-6): its stage offers OPEN › on their
  // last-opened character.
  return 'landing';
}

// Parse a pathname into { screen, charId }. Returns { screen: null }
// for unknown paths so the caller can decide on a fallback. Both the
// cold-load initializer and the popstate handler use this.
function parsePathToScreen(path) {
  // Strip trailing slash for canonical comparison.
  var p = (path || '').replace(/\/$/, '');
  if (p === '' || p === '/' || p === '/player' || p === '/player.html') {
    return { screen: 'landing' };
  }
  // Match /player/sheet/[id]/store
  var storeMatch = p.match(/^\/player\/sheet\/([^/]+)\/store$/);
  if (storeMatch) return { screen: 'store', charId: storeMatch[1] };
  var modifyMatch = p.match(/^\/player\/sheet\/([^/]+)\/modify$/);   // F-100 M13 R-M13B-2
  if (modifyMatch) return { screen: 'modify', charId: modifyMatch[1] };
  // Match /player/sheet/[id]
  var sheetMatch = p.match(/^\/player\/sheet\/([^/]+)$/);
  if (sheetMatch) return { screen: 'sheet', charId: sheetMatch[1] };
  // B-863 · R-NPC-4: /player/npc/<tail> — the library's position; the module's grammar reads the tail
  // (and REFUSES `encounters`/`custom` here: the player declares neither capability).
  var npcMatch = p.match(/^\/player\/npc\/(.+)$/);
  if (npcMatch) return { screen: 'npc', npcPath: npcMatch[1] };
  // Match /player/yard/[vehicleKey] (R-Y2-2 front door — the entry page)
  var yardMatch = p.match(/^\/player\/yard\/([^/]+)$/);
  if (yardMatch) return { screen: 'yard', vehicleKey: decodeURIComponent(yardMatch[1]) };
  // Single-segment routes
  switch (p) {
    // B-650 · R-LFM-6: the roster's old URL opens the landing on its INDEX (the roster). The URL is
    // not rewritten, so a bookmark on it stays valid and back/forward through it keep working.
    case '/player/roster':       return { screen: 'landing', zone: 'index' };
    case '/player/pregen':       return { screen: 'pregen' };
    case '/player/quickbuild':   return { screen: 'quickbuild' };
    case '/player/custom':       return { screen: 'custom' };
    case '/player/npc':          return { screen: 'npc' };
    case '/player/import':       return { screen: 'import' };  // OGG-1 import surface
    case '/player/backup':       return { screen: 'backup' };  // RELEASE R3 (D-258): the whole-save backup
    case '/player/store':        return { screen: 'store' };   // ITM-V1 top-level store
    case '/player/yard':         return { screen: 'yard' };    // R-Y2-2 the player Ship Yard (front door)
    // /player/dice-sandbox RETIRED (UXQP-10) — falls to the unknown-path
    // default; the dice surface lives at /dice.
    default:                     return { screen: null };
  }
}

/* F-100 C2 · THE HOMEBREW EDITOR'S ROUTES (ruling `f100-items-editor-contracts` R-FIEC-5). The parser above
   stays pure and answers `{screen: null}` for every /player/homebrew path, exactly as before. This wrapper is
   the one place the editor's switch bends a parse: ON, a /player/homebrew path is the `homebrew` screen (the
   editor reads the rest of the path itself, `SWRPGEditor.parse`); OFF, it answers nothing and today's
   unknown-path fallback (the landing) stands. */
function homebrewScreenFor(path) {
  return (window.SWRPGEditor && window.SWRPGEditor.screenFor(path)) ? 'homebrew' : null;
}
/* SHIP YARD S4 · K6'S ROUTES (R-S4G-3). The parser above stays pure. ANY /player/yard path is the `yard` screen and its
   tail is the Yard's to read (`SWRPGVesselView.yardRoute` — hangar · catalogue · catalogue/<key> · ship/<id>[/<tab>] ·
   unit/<id>, a lone <key> the ENTRY's alias, anything else not-found IN PLACE, never the landing). K9 bent this parse
   until the S5 flip retired it (R-S5R-18). */
function yardScreenFor(path) {
  var m = /^\/player\/yard(?:\/(.*))?$/.exec(String(path || '').replace(/\/$/, ''));
  return m ? (m[1] || '') : null;
}

/* ══════════════════════════════════════════════════════
   APP ROOT
══════════════════════════════════════════════════════ */
// Small localStorage-backed toggle for the suite ⚙ dice view-prefs (View Odds / Interpret Roll).
// Keys are shared with HoloDice; the sheet dice modal (diceUI.jsx) reads them on open. (Polish P1
// — player ⚙ parity; Sound is excluded, the flat modal plays no audio.)
function useLocalToggle(key) {
  var _s = useState(function() { try { return window.localStorage.getItem(key) === '1'; } catch (e) { return false; } });
  var on = _s[0], setOn = _s[1];
  var toggle = useCallback(function() {
    setOn(function(v) {
      var next = !v;
      try { window.localStorage.setItem(key, next ? '1' : '0'); } catch (e) {}
      return next;
    });
  }, [key]);
  return { enabled: on, toggle: toggle };
}

// ── Store-bar icon helpers (ITM-V1, ADR 0010) ─────────────────────
// The contextual store bar reuses the kernel's silhouette glyphs; navBadge wraps any bar icon
// with a count bubble (COUNTER(n) / HOLDS(n) / the global STORE tab while a cart is piled).
function storeGlyph(family) {
  var S = window.SWRPGStore;
  return S ? S.glyph(family, 20) : navIcon('shopping-cart');
}
function holdsGlyph() {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor"
      strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M12 3l7.5 9-7.5 9-7.5-9z" />
    </svg>
  );
}
// B-679 — `paper` returns the badge WITHOUT a positioned wrapper of its own, because the paper tab
// already draws one: `BottomNav`'s glyph span becomes the board's `.pb-mark{position:relative}`, and a
// second wrapper here would nest `.pb-mark` inside `.pb-mark` where the frame's markup has exactly
// one. The COUNT and its 99 cap are the app's and do not move — the holds badge is still the length of
// the holds list and the counter badge still the SUM of the slip's quantities (`cartCount`, never the
// number of lines). Only the ground and the ink move: `.pb-badge` is `--doc-mark` filled with ink on
// it, which is that token's own documented job.
function navBadge(icon, count, paper) {
  var badge = count > 0 ? (paper
    ? <span aria-hidden="true" className="pb-badge">{count > 99 ? '99' : count}</span>
    : <span aria-hidden="true" style={{
        position: 'absolute', top: -5, right: -9, minWidth: 14, height: 14,
        padding: '0 3px', borderRadius: 8, boxSizing: 'border-box',
        background: 'rgba(245,200,66,0.92)', color: '#1a1406',
        fontFamily: 'var(--font-mono)', fontSize: 'var(--fs-2xs)', fontWeight: 700,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
      }}>{count > 99 ? '99' : count}</span>) : null;
  if (paper) return <React.Fragment>{icon}{badge}</React.Fragment>;
  return (
    <span style={{ position: 'relative', display: 'flex', lineHeight: 0 }}>
      {icon}
      {badge}
    </span>
  );
}

// Reactive "wide desktop" gate for the master-detail RAIL (ruling sheet-immersive-table-mode-brief FORK 4):
// the character rail only earns its 320px on a genuine desktop (≥1367px). At tablet widths (1024–1366) the
// sheet goes full-width and roster⇄sheet switches like the phone. matchMedia so it reacts to rotation/resize.
function useWideDesktop() {
  var _s = React.useState(function () { try { return !!(window.matchMedia && window.matchMedia(window.SWRPGBands.MQ_WIDE).matches); } catch (e) { return false; } });
  var wide = _s[0], set = _s[1];
  React.useEffect(function () {
    try {
      var mq = window.matchMedia(window.SWRPGBands.MQ_WIDE);
      var on = function () { set(mq.matches); };
      mq.addEventListener ? mq.addEventListener('change', on) : mq.addListener(on);
      return function () { mq.removeEventListener ? mq.removeEventListener('change', on) : mq.removeListener(on); };
    } catch (e) {}
  }, []);
  return wide;
}

// THE CREATOR'S BAND HOOK (lap C1, ruling `creator-c1-mechanical` — the fork ruled (b)).
//
// Three bands, ONE meaning each: mobile < 1024 · mid 1024–1366 · wide >= 1367 — the ladder's one
// home is lib/shared/bands.js (audit item B); the seams here are read from it, never typed.
//
// COMPOSED, NOT INVENTED. The concept ruling's other sentence ("`data-layout` grows a third
// value") was AMENDED away in favour of this: growing that enum would change a vocabulary three
